//! NAMES ARE CONTRACT: statics carry the exact JS export names. The value is the JS
//! value, pressed at expansion time and proven by the conform 'const' lane (ε0 full-value
//! equality). Drift watch re-opens the unit if the JS source changes.
// QUALITY: 78/100 — generated data twin: proven byte-fidelity (ε0 full-value), embedded blob unreadable by design
use serde_json::Value;
use std::sync::LazyLock;

pub static TIMELINE_SCHEMA: LazyLock<Value> = LazyLock::new(|| {
    serde_json::from_str(r#""\nCREATE TABLE IF NOT EXISTS timeline.sacred_timeline (\n  id              INTEGER PRIMARY KEY AUTOINCREMENT,\n  ts              TEXT    NOT NULL DEFAULT (datetime('now')),\n  actor           TEXT    NOT NULL,\n  operation       TEXT    NOT NULL,\n  entity_type     TEXT    NOT NULL,\n  entity_id       TEXT    NOT NULL,\n  before_json     TEXT,\n  after_json      TEXT,\n  payload         TEXT,\n  prev_print      TEXT    NOT NULL,\n  digital_print   TEXT    NOT NULL UNIQUE,\n  -- FEAT-AUDIT-USER-GOAL-LINK (mig 033): correlation back to the interviewer\n  -- turn that triggered this work. NOT hashed into digital_print — purely\n  -- metadata. NULL = caller did not declare a user goal (background jobs,\n  -- seeding, migrations). Cross-DB FK (interviewer_turns is in state) — not\n  -- enforced by SQLite, convention only, same as before relocation.\n  user_goal_id    INTEGER,\n  -- EPIC-DRIVER-WATERFALL-REDESIGN (mig 148): WHERE the action ran —\n  -- worktree:<path> | sandbox:<path> | live, derived from the contract entity.\n  -- NOT hashed into digital_print (metadata, like user_goal_id). NULL when the\n  -- mutated entity is not a contract (no build env).\n  exec_env        TEXT,\n  -- EPIC-AUDIT-PACK (mig 150): the brain.driver_ticks.id that produced this\n  -- seal, stamped by flushAuditPack. The DETERMINISTIC tick↔timeline link —\n  -- replaces the timestamp+slug heuristic for \"which seals did this tick\n  -- produce\". NOT hashed into digital_print (metadata, like user_goal_id /\n  -- exec_env). Cross-DB logical FK (driver_ticks is in brain) — not enforced by\n  -- SQLite, convention only. NULL for seals not produced under an audit pack\n  -- (the default immediate path).\n  tick_id         INTEGER\n);\nCREATE INDEX IF NOT EXISTS timeline.idx_timeline_entity ON sacred_timeline(entity_type, entity_id);\nCREATE INDEX IF NOT EXISTS timeline.idx_timeline_ts     ON sacred_timeline(ts);\n-- user-goal correlation index (was migration 033, on the old main copy).\n-- Folded here so the relocated table keeps the optimization on fresh DBs.\nCREATE INDEX IF NOT EXISTS timeline.idx_timeline_user_goal ON sacred_timeline(user_goal_id) WHERE user_goal_id IS NOT NULL;\n-- SACRED_TIMELINE_ROWS_MUST_HAVE_DIGITAL_PRINT (DB-layer enforcement of the\n-- history-is-sacred law): rows are write-once — no UPDATE, no DELETE.\nCREATE TRIGGER IF NOT EXISTS timeline.sacred_timeline_no_update\n  BEFORE UPDATE ON sacred_timeline\n  BEGIN SELECT RAISE(ABORT, 'sacred_timeline rows are immutable (law: SACRED_TIMELINE_ROWS_MUST_HAVE_DIGITAL_PRINT)'); END;\nCREATE TRIGGER IF NOT EXISTS timeline.sacred_timeline_no_delete\n  BEFORE DELETE ON sacred_timeline\n  BEGIN SELECT RAISE(ABORT, 'sacred_timeline rows are immutable — no DELETE (law: SACRED_TIMELINE_ROWS_MUST_HAVE_DIGITAL_PRINT)'); END;\n-- EVENT-SOURCED-AUDIT (Phase 2): durable pre-chain STAGING buffer. The driver\n-- accumulates a run's seal rows here (cheap append, NO hash chain) as each skill\n-- runs, then flushes them into sacred_timeline in ONE batch at a phase / failure\n-- / pause boundary (flushAuditStage). Unlike sacred_timeline this is MUTABLE —\n-- rows are DELETEd once sealed (it is a buffer, not the canonical log). Field-\n-- capped at the source (with-audit) like the log, so it never re-bloats.\nCREATE TABLE IF NOT EXISTS timeline.audit_stage (\n  id            INTEGER PRIMARY KEY AUTOINCREMENT,\n  session_id    TEXT,\n  tick_id       INTEGER,\n  phase         TEXT,\n  ts            TEXT    NOT NULL DEFAULT (datetime('now')),\n  actor         TEXT    NOT NULL,\n  operation     TEXT    NOT NULL,\n  entity_type   TEXT    NOT NULL,\n  entity_id     TEXT    NOT NULL,\n  before_json   TEXT,\n  after_json    TEXT,\n  payload       TEXT,\n  exec_env      TEXT,\n  user_goal_id  INTEGER\n);\nCREATE INDEX IF NOT EXISTS timeline.idx_audit_stage_session ON audit_stage(session_id, id);\n""#).expect("TIMELINE_SCHEMA: embedded JSON is valid by construction")
});

pub static JUDGMENTS_SCHEMA: LazyLock<Value> = LazyLock::new(|| {
    serde_json::from_str(r#""\nCREATE TABLE IF NOT EXISTS judgments.judgment_cases (\n  judgment_id      TEXT    PRIMARY KEY,\n  card_slug        TEXT    NOT NULL,\n  scope_kind       TEXT    NOT NULL,\n  scope_ref        TEXT    NOT NULL DEFAULT '',\n  goal_line        TEXT,                         -- the single measurable goal (derived from acceptance)\n  n_items          INTEGER,\n  defender_trues   INTEGER,\n  prosecutor_trues INTEGER,\n  defender_rate    REAL,\n  prosecutor_rate  REAL,\n  defender_accuracy   REAL,                      -- mean judge accuracy grade (0–1) over the side's items\n  prosecutor_accuracy REAL,\n  verdict          TEXT,                         -- 'pass' | 'fail' | 'invalid' | NULL (pending)\n  created_at       TEXT    NOT NULL DEFAULT (datetime('now')),\n  updated_at       TEXT    NOT NULL DEFAULT (datetime('now'))\n);\nCREATE INDEX IF NOT EXISTS judgments.idx_judgment_cases_card ON judgment_cases(card_slug, created_at DESC);\n\nCREATE TABLE IF NOT EXISTS judgments.judgment_items (\n  id           INTEGER PRIMARY KEY AUTOINCREMENT,\n  judgment_id  TEXT    NOT NULL,\n  side         TEXT    NOT NULL CHECK (side IN ('defender','prosecutor')),\n  item_id      TEXT    NOT NULL,\n  statement    TEXT    NOT NULL DEFAULT '',\n  links_json   TEXT    NOT NULL DEFAULT '[]',\n  grounded     INTEGER NOT NULL DEFAULT 1,\n  judge_value  INTEGER,                          -- 1/0 = true/false; NULL pending\n  judge_accuracy REAL,                           -- judge's 0–1 grade: how well the cited evidence supports the claim\n  judge_why    TEXT,\n  created_at   TEXT    NOT NULL DEFAULT (datetime('now')),\n  UNIQUE (judgment_id, side, item_id)\n);\nCREATE INDEX IF NOT EXISTS judgments.idx_judgment_items_jid ON judgment_items(judgment_id, side);\n\nCREATE TABLE IF NOT EXISTS judgments.judgment_calls (\n  id           INTEGER PRIMARY KEY AUTOINCREMENT,\n  judgment_id  TEXT    NOT NULL,\n  role         TEXT    NOT NULL,                 -- 'evidence.gather' | 'defender' | 'prosecutor' | 'judge.defender' | 'judge.prosecutor'\n  tier         TEXT,\n  prompt_md    TEXT,\n  response_md  TEXT,\n  ai_call_id   INTEGER,                          -- correlate to brain.ai_calls (cross-DB, by convention)\n  created_at   TEXT    NOT NULL DEFAULT (datetime('now'))\n);\nCREATE INDEX IF NOT EXISTS judgments.idx_judgment_calls_jid ON judgment_calls(judgment_id, created_at);\n\n-- FEAT-COURT-DETERMINISTIC-EVIDENCE: the deterministic gather step persists the\n-- evidence bundle it assembled (card+contract+blueprint+screening) as a durable\n-- JSON artifact BEFORE the debate — the court's research-of-record. One row per\n-- judgment (re-gather upserts). The debaters argue from it; the FE renders it as\n-- the first court step.\nCREATE TABLE IF NOT EXISTS judgments.court_evidence (\n  judgment_id   TEXT    PRIMARY KEY,\n  contract_slug TEXT    NOT NULL,\n  scope_kind    TEXT    NOT NULL DEFAULT '',\n  scope_ref     TEXT    NOT NULL DEFAULT '',\n  corpus_json   TEXT    NOT NULL,                -- the FULL gathered evidence bundle (the json of evidences)\n  evidence_md   TEXT,                            -- the rendered, citable evidence the debaters + judge read\n  n_acceptance  INTEGER NOT NULL DEFAULT 0,\n  n_microtasks  INTEGER NOT NULL DEFAULT 0,\n  n_blocks      INTEGER NOT NULL DEFAULT 0,\n  n_nested_blocks INTEGER NOT NULL DEFAULT 0,\n  has_card      INTEGER NOT NULL DEFAULT 0,\n  has_blueprint INTEGER NOT NULL DEFAULT 0,\n  has_screening INTEGER NOT NULL DEFAULT 0,\n  created_at    TEXT    NOT NULL DEFAULT (datetime('now'))\n);\nCREATE INDEX IF NOT EXISTS judgments.idx_court_evidence_contract ON court_evidence(contract_slug, created_at DESC);\n""#).expect("JUDGMENTS_SCHEMA: embedded JSON is valid by construction")
});

pub static STATE_SCHEMA: LazyLock<Value> = LazyLock::new(|| {
    serde_json::from_str(r#""\n-- sacred_timeline relocated to its own DB (TIMELINE_SCHEMA, attached as\n-- 'timeline'). The view + timeline_commits below reference it by its\n-- unqualified name, which resolves to the attached copy at query time.\n-- idx_timeline_user_goal lives in migration 033 (depends on user_goal_id\n-- column being present, which on existing DBs is added by that migration).\n\nCREATE TABLE IF NOT EXISTS cards (\n  id          INTEGER PRIMARY KEY AUTOINCREMENT,\n  slug        TEXT    NOT NULL UNIQUE,\n  title       TEXT    NOT NULL,\n  status      TEXT    NOT NULL DEFAULT 'backlog',\n  body_json   TEXT,\n  -- PIPELINE-V2: the card's high-level acceptance as a STRUCTURED ARRAY (the features —\n  -- [{id, intent}]), written by the PL screening clarify leg. The contract's acceptance\n  -- S-tasks link back to these via card_acceptance_id; PL Ratify compares the two.\n  acceptance_json TEXT NOT NULL DEFAULT '[]',\n  -- FEAT-CARD-SCORING: 1-5 numeric facets + computed score (risk × complexity × priority).\n  -- NULL until board-keeper.card.score (AI auto-score) or manual update sets them.\n  risk        INTEGER CHECK (risk IS NULL OR (risk BETWEEN 1 AND 5)),\n  complexity  INTEGER CHECK (complexity IS NULL OR (complexity BETWEEN 1 AND 5)),\n  priority    INTEGER CHECK (priority IS NULL OR (priority BETWEEN 1 AND 5)),\n  score       INTEGER, -- product of the three; reserved for sort. NULL if any facet missing.\n  -- FEAT-CARDS-PARENT-CHILD: epic membership. Self-ref FK; NULL means top-level (epic itself or standalone card).\n  parent_slug TEXT REFERENCES cards(slug),\n  -- EPIC-TUI-GOD-MODE (migration 042): when 1, driver state-machine\n  -- routes this card past PL straight to contract.draft.auto. Only\n  -- god-mode actions (TTY-gated) can flip it.\n  skip_pl_flag INTEGER NOT NULL DEFAULT 0,\n  -- EPIC-CARD-DRIVER-CONTROL (migration 057, card #395): operator pickup\n  -- control. driver_intent IN ('paused','stopped') excludes the card\n  -- from driver-schedule; 'play' pins it to the front of the queue.\n  driver_intent TEXT NOT NULL DEFAULT 'auto'\n    CHECK (driver_intent IN ('auto', 'play', 'paused', 'stopped')),\n  -- FEAT-CARD-AWAITING-CHILDREN-STATUS: when a parent card entered\n  -- status='awaiting_children'. Folded into the base schema 2026-06-11 —\n  -- it lived only in its migration, so :memory: test DBs lacked the\n  -- column cards-active selects.\n  awaiting_children_at TEXT,\n  -- EPIC-CARD-DISPLAY-ORDER (migration 058): operator-controlled ordering\n  -- within a parent scope (siblings of an EPIC, or NULL-parent free cards).\n  -- NULL = no manual order, sort by created_at/id. REAL allows fractional\n  -- midpoints on insert between two ordered cards (no renumber needed at\n  -- typical scale).\n  display_order REAL DEFAULT NULL,\n  -- FEAT-CARD-RUN-PREFLIGHT (migration 115): PL accuracy gate. Folded into\n  -- the base schema (precedent: skip_pl_flag/driver_intent above) so fresh\n  -- DBs — including :memory: test DBs that never run migrations — match the\n  -- columns board.service.listCards SELECTs. Persisted DBs got them via the\n  -- migration's ALTER; CREATE TABLE IF NOT EXISTS leaves those untouched.\n  accuracy_score       INTEGER,\n  accuracy_detail_json TEXT,\n  accuracy_computed_at TEXT,\n  -- FEAT-OPENROUTER-SESSION-TRACKING (migration 137): the OpenRouter\n  -- session id for the card's CURRENT run. Get-or-created by the driver\n  -- at tick start, threaded to the provider body via AsyncLocalStorage,\n  -- cleared by the rewind/restart skills so a stopped/stuck-then-restarted\n  -- card starts a fresh session. NULL = no active run.\n  openrouter_session_id TEXT,\n  -- FEAT-CARD-RESET-CLONE-ARCHIVE: \"reset card\" is clone+archive (history is\n  -- immutable). The fresh clone points back at the card it was reset from via\n  -- this self-ref FK (mirrors superseded_by across contracts/blueprints/laws).\n  -- NULL = an originally-authored card (not a reset clone).\n  cloned_from TEXT REFERENCES cards(slug),\n  -- FEAT-DRIVER-PR-GATE: 1 = merge the worktree immediately at QA-green (the old behavior);\n  -- 0 (default) = open a pull request on the Pulls screen and wait for the operator's merge.\n  auto_merge  INTEGER NOT NULL DEFAULT 0,\n  created_at  TEXT    NOT NULL DEFAULT (datetime('now')),\n  updated_at  TEXT    NOT NULL DEFAULT (datetime('now'))\n);\n-- idx_cards_parent_slug created in a defensive JS step after exec()\n-- (see openDb after STATE_SCHEMA exec). The partial-index can't be\n-- inside STATE_SCHEMA because pre-019 persisted DBs may lack the column.\n\n-- FEAT-SQLITE-GIT-SYNC: append-only snapshots of card state per branch/sha.\nCREATE TABLE IF NOT EXISTS card_revisions (\n  id            INTEGER PRIMARY KEY AUTOINCREMENT,\n  card_slug     TEXT    NOT NULL REFERENCES cards(slug),\n  branch        TEXT    NOT NULL,\n  sha           TEXT,\n  snapshot_json TEXT    NOT NULL,\n  captured_at   TEXT    NOT NULL DEFAULT (datetime('now'))\n);\nCREATE INDEX IF NOT EXISTS idx_card_revisions_branch ON card_revisions(branch);\nCREATE INDEX IF NOT EXISTS idx_card_revisions_slug   ON card_revisions(card_slug);\n\n-- FEAT-SANDBOX-LIFECYCLE: active sandbox phase per card.\nCREATE TABLE IF NOT EXISTS card_sandbox (\n  card_slug     TEXT PRIMARY KEY REFERENCES cards(slug),\n  current_phase TEXT NOT NULL CHECK (current_phase IN ('research','contract','impl','review','closed')),\n  started_at    TEXT NOT NULL DEFAULT (datetime('now')),\n  updated_at    TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\n-- FEAT-FILE-SENSITIVITY-TABLE: path patterns → risk weights for deterministic complexity scoring.\nCREATE TABLE IF NOT EXISTS file_sensitivity (\n  id           INTEGER PRIMARY KEY AUTOINCREMENT,\n  path_glob    TEXT    NOT NULL UNIQUE,\n  risk_weight  INTEGER NOT NULL CHECK (risk_weight BETWEEN 1 AND 5),\n  description  TEXT,\n  created_at   TEXT    NOT NULL DEFAULT (datetime('now'))\n);\n\n-- FEAT-WORKSPACE-MODEL: the managed project antiloki points at. root_path is\n-- the workspace root (where the driver sandboxes, git runs, browsed code lives).\n-- Exactly one row is active. Self-hosting = the active row's root_path is the\n-- substrate install. Defaults to a single seeded 'self' row.\nCREATE TABLE IF NOT EXISTS workspaces (\n  id           INTEGER PRIMARY KEY AUTOINCREMENT,\n  name         TEXT    NOT NULL UNIQUE,\n  root_path    TEXT    NOT NULL,\n  vcs          TEXT    NOT NULL DEFAULT 'git',\n  is_active    INTEGER NOT NULL DEFAULT 0,\n  -- db_dir = substrate-relative dir holding THIS workspace's own 5-DB set\n  -- (.antiloki/workspaces/<name>/db). NULL for the 'self' row (self-hosting\n  -- uses the substrate's own DBs). The openDb resolver reads this to decide\n  -- which DB set to attach at boot. (FEAT-WORKSPACE-CRUD-API)\n  db_dir       TEXT,\n  created_at   TEXT    NOT NULL DEFAULT (datetime('now'))\n);\n\n-- FEAT-CARD-TAGS-DICT: closed-vocab tag registry + many-to-many join.\nCREATE TABLE IF NOT EXISTS tags (\n  slug         TEXT    PRIMARY KEY,\n  description  TEXT,\n  kind         TEXT    NOT NULL DEFAULT 'theme' CHECK (kind IN ('theme','surface','risk','tooling')),\n  created_at   TEXT    NOT NULL DEFAULT (datetime('now'))\n);\nCREATE TABLE IF NOT EXISTS card_tags (\n  card_slug    TEXT NOT NULL REFERENCES cards(slug),\n  tag_slug     TEXT NOT NULL REFERENCES tags(slug),\n  joined_at    TEXT NOT NULL DEFAULT (datetime('now')),\n  PRIMARY KEY (card_slug, tag_slug)\n);\nCREATE INDEX IF NOT EXISTS idx_card_tags_tag ON card_tags(tag_slug);\n\n-- FEAT-SPRINTS: ported from v1. Sprint groups cards into a capacity-bounded batch.\nCREATE TABLE IF NOT EXISTS sprints (\n  id          INTEGER PRIMARY KEY AUTOINCREMENT,\n  slug        TEXT    NOT NULL UNIQUE,\n  goal_md     TEXT,\n  capacity_pts INTEGER NOT NULL DEFAULT 0,\n  started_at  TEXT    NOT NULL DEFAULT (datetime('now')),\n  ended_at    TEXT\n);\nCREATE TABLE IF NOT EXISTS sprint_items (\n  id           INTEGER PRIMARY KEY AUTOINCREMENT,\n  sprint_slug  TEXT    NOT NULL REFERENCES sprints(slug),\n  card_slug    TEXT    NOT NULL REFERENCES cards(slug),\n  phase        TEXT    NOT NULL DEFAULT 'impl' CHECK (phase IN ('impl','qa','done')),\n  est_pts      INTEGER NOT NULL DEFAULT 1,\n  added_at     TEXT    NOT NULL DEFAULT (datetime('now')),\n  UNIQUE (sprint_slug, card_slug)\n);\nCREATE INDEX IF NOT EXISTS idx_sprint_items_sprint ON sprint_items(sprint_slug);\n\n-- FEAT-PHASE-EVENTS-LEDGER: per-card lifecycle ledger.\n-- Phases: pl_draft, tl_sign, dev_impl, qa_pass, close (extensible).\n-- Append-only — no UPDATE, no DELETE.\nCREATE TABLE IF NOT EXISTS card_phase_events (\n  id           INTEGER PRIMARY KEY AUTOINCREMENT,\n  card_slug    TEXT    NOT NULL REFERENCES cards(slug),\n  phase        TEXT    NOT NULL,\n  actor        TEXT    NOT NULL,\n  ts           TEXT    NOT NULL DEFAULT (datetime('now')),\n  evidence_json TEXT\n);\nCREATE INDEX IF NOT EXISTS idx_card_phase_events_slug  ON card_phase_events(card_slug);\nCREATE INDEX IF NOT EXISTS idx_card_phase_events_phase ON card_phase_events(phase);\n\n-- FEAT-PROJECT-JOURNEY-NARRATIVE (EPIC-AUTONOMOUS-LOOP-CLOSING):\n-- Chronological prose narrative of the project. One row per closed\n-- card; written by keeper.journey.append after keeper.card.consolidate\n-- produces the lesson memory. memory_id links back to that memory.\nCREATE TABLE IF NOT EXISTS project_journey (\n  id            INTEGER PRIMARY KEY AUTOINCREMENT,\n  ts            TEXT    NOT NULL DEFAULT (datetime('now')),\n  card_slug     TEXT    NOT NULL,\n  narrative_md  TEXT    NOT NULL,\n  verdict       TEXT,\n  lessons_json  TEXT,\n  metrics_json  TEXT,\n  memory_id     INTEGER,\n  FOREIGN KEY (card_slug) REFERENCES cards(slug)\n);\nCREATE INDEX IF NOT EXISTS idx_project_journey_ts        ON project_journey(ts);\nCREATE INDEX IF NOT EXISTS idx_project_journey_card_slug ON project_journey(card_slug);\n\n-- timeline_commits stays in main (git-correlation side table), but its\n-- timeline_id now points at sacred_timeline in the ATTACHED timeline DB.\n-- SQLite FKs cannot span attached databases (see the header note), so the\n-- former FOREIGN KEY (timeline_id) REFERENCES sacred_timeline(id) is dropped\n-- and the link is convention-only — written only by git-commit-card with a\n-- real sacred_timeline.id. Migration 138 rebuilds existing copies to match.\nCREATE TABLE IF NOT EXISTS timeline_commits (\n  timeline_id   INTEGER PRIMARY KEY,\n  git_sha       TEXT    NOT NULL,\n  committed_at  TEXT    NOT NULL DEFAULT (datetime('now'))\n);\n\n-- notifications: driver failures, daemon stops, halts. TUI surfaces\n-- undismissed count in the status bar.\n-- DRIVER-FAILURE-OBSERVABILITY (migration 043).\nCREATE TABLE IF NOT EXISTS notifications (\n  id            INTEGER PRIMARY KEY,\n  ts            TEXT    NOT NULL DEFAULT (datetime('now')),\n  -- kind widened by migration 175 (2026-07-11): the frozen five-value enum\n  -- silently ate maybeHeimdallDigest's INSERT on every idle tick (its catch\n  -- swallowed the CHECK failure), so the weekly digest never fired.\n  kind          TEXT    NOT NULL CHECK (kind IN ('driver-tick-failed','driver-tick-escalated','daemon-stop','daemon-error','generic','heimdall_digest','bloat_detect')),\n  severity      TEXT    NOT NULL DEFAULT 'warn' CHECK (severity IN ('info','warn','error')),\n  source        TEXT    NOT NULL,\n  message       TEXT    NOT NULL,\n  related_card_slug TEXT,\n  payload_json  TEXT,\n  dismissed_at  TEXT\n);\nCREATE INDEX IF NOT EXISTS idx_notif_undismissed ON notifications(dismissed_at, ts DESC) WHERE dismissed_at IS NULL;\nCREATE INDEX IF NOT EXISTS idx_notif_kind ON notifications(kind, ts DESC);\n\n-- EPIC-INBOX-AS-EMAIL-ATTENTION-SURFACE (migration 065): rich email-\n-- style attention surface. Each substrate event that needs operator\n-- awareness writes a row with formatted body_md. The TUI Inbox mode\n-- renders these as expandable emails; notifications shrink to short\n-- pointers (\"N new in Inbox: <subject>\").\nCREATE TABLE IF NOT EXISTS inbox_messages (\n  id                        INTEGER PRIMARY KEY AUTOINCREMENT,\n  ts                        TEXT    NOT NULL DEFAULT (datetime('now')),\n  kind                      TEXT    NOT NULL,\n  subject                   TEXT    NOT NULL,\n  body_md                   TEXT    NOT NULL,\n  severity                  TEXT    NOT NULL DEFAULT 'info'\n    CHECK (severity IN ('info', 'warn', 'error')),\n  related_card_slug         TEXT,\n  related_contract_slug     TEXT,\n  suggested_reconciler      TEXT,\n  suggested_card_action     TEXT,\n  payload_json              TEXT,\n  read_at                   TEXT,\n  archived_at               TEXT\n);\nCREATE INDEX IF NOT EXISTS idx_inbox_unread ON inbox_messages(archived_at, read_at, ts DESC) WHERE archived_at IS NULL;\nCREATE INDEX IF NOT EXISTS idx_inbox_card ON inbox_messages(related_card_slug) WHERE related_card_slug IS NOT NULL;\n\n-- triage_recommendation_states (migration 059, EPIC-TRIAGE-AS-BOARD-ADVISOR):\n-- operator decisions on Triage Overview advisories. Append-only.\nCREATE TABLE IF NOT EXISTS triage_recommendation_states (\n  id          INTEGER PRIMARY KEY AUTOINCREMENT,\n  rec_id      TEXT    NOT NULL,\n  state       TEXT    NOT NULL CHECK (state IN ('note', 'schedule')),\n  marked_at   TEXT    NOT NULL DEFAULT (datetime('now')),\n  marked_by   TEXT    NOT NULL,\n  expires_at  TEXT,\n  note_text   TEXT\n);\nCREATE INDEX IF NOT EXISTS idx_triage_rec_states_rec_id ON triage_recommendation_states(rec_id, marked_at DESC);\n\n-- pending_diffs: AI-proposed file changes awaiting human approval.\n-- Backed by migration 20260522-041; mirrored here so in-memory DBs\n-- used in tests get the schema without running migrations.\n-- AI-DIFF-PROPOSAL-FLOW (card 237).\nCREATE TABLE IF NOT EXISTS pending_diffs (\n  id              INTEGER PRIMARY KEY,\n  card_slug       TEXT    NOT NULL,\n  file_path       TEXT    NOT NULL,\n  diff_text       TEXT    NOT NULL,\n  proposed_by     TEXT    NOT NULL,\n  status          TEXT    NOT NULL DEFAULT 'pending'\n                          CHECK (status IN ('pending','approved','rejected','applied','superseded')),\n  proposed_at     TEXT    NOT NULL DEFAULT (datetime('now')),\n  decided_at      TEXT,\n  decided_by      TEXT,\n  decision_reason TEXT,\n  applied_at      TEXT,\n  applied_sha     TEXT\n);\nCREATE INDEX IF NOT EXISTS idx_pending_diffs_card    ON pending_diffs(card_slug, status);\nCREATE INDEX IF NOT EXISTS idx_pending_diffs_status  ON pending_diffs(status, proposed_at);\nCREATE INDEX IF NOT EXISTS idx_pending_diffs_file    ON pending_diffs(file_path, status);\n\nCREATE TABLE IF NOT EXISTS agents (\n  id                INTEGER PRIMARY KEY AUTOINCREMENT,\n  name              TEXT    NOT NULL UNIQUE,\n  description       TEXT    NOT NULL,\n  skills_json       TEXT    NOT NULL DEFAULT '[]',\n  context_json      TEXT    NOT NULL DEFAULT '{}',\n  permissions_json  TEXT    NOT NULL DEFAULT '{}',\n  model             TEXT,\n  -- EPIC-FE-PERSONA-PROFILE-SCREENS (migration 116): operator-authored prompt\n  -- appended to the agent's core context. Never overwrites the core (which\n  -- stays in context_json); nullable, audited, reversible.\n  custom_prompt_md  TEXT,\n  -- EPIC-SUBAGENT (migration 144): the specialization tree. parent_agent is the\n  -- inheritance edge (NULL = a root/base persona); specialization_md is the leaf's\n  -- delta prompt (composed onto the parent's persona by agent-persona-resolve);\n  -- applies_to_json is the deterministic routing/lint match vocab {globs,langs,tags};\n  -- is_abstract=1 marks a pure TAG never dispatched directly (leaf-only execution).\n  -- All additive + nullable → existing flat agents are unchanged (parent NULL → root).\n  parent_agent      TEXT    REFERENCES agents(name),\n  specialization_md TEXT,\n  applies_to_json   TEXT,\n  is_abstract       INTEGER NOT NULL DEFAULT 0,\n  created_at        TEXT    NOT NULL DEFAULT (datetime('now')),\n  updated_at        TEXT    NOT NULL DEFAULT (datetime('now'))\n);\n\n-- actions: intent-named, permission-gated, audit-traced, MCP-exposed\n-- dispatch entry points. Compose 1+ actions via steps_json. Was: actions.\nCREATE TABLE IF NOT EXISTS actions (\n  id                INTEGER PRIMARY KEY AUTOINCREMENT,\n  name              TEXT    NOT NULL UNIQUE,\n  description       TEXT    NOT NULL,\n  owner_agent       TEXT    NOT NULL,\n  steps_json        TEXT    NOT NULL,\n  returns           TEXT,\n  on_failure        TEXT    NOT NULL DEFAULT 'abort',\n  verification_json TEXT,   -- per-action verification spec (migration 049)\n  kind              TEXT    DEFAULT 'atomic'  -- card #377; metadata-only categorization\n                            CHECK (kind IS NULL OR kind IN ('atomic', 'workflow')),\n  created_at        TEXT    NOT NULL DEFAULT (datetime('now')),\n  updated_at        TEXT    NOT NULL DEFAULT (datetime('now')),\n  FOREIGN KEY (owner_agent) REFERENCES agents(name)\n);\n\n-- agent_actions: relational permissions. Append-only: revoke sets\n-- revoked_at, never DELETE — preserves audit history of who-could-do-what-when.\n-- Was: agent_actions.\nCREATE TABLE IF NOT EXISTS agent_actions (\n  id              INTEGER PRIMARY KEY AUTOINCREMENT,\n  agent_name      TEXT NOT NULL,\n  action_name     TEXT NOT NULL,\n  granted_at      TEXT NOT NULL DEFAULT (datetime('now')),\n  granted_by      TEXT NOT NULL,\n  conditions_json TEXT,\n  revoked_at      TEXT,\n  revoked_by      TEXT,\n  FOREIGN KEY (agent_name)  REFERENCES agents(name),\n  FOREIGN KEY (action_name) REFERENCES actions(name)\n);\n\nCREATE INDEX IF NOT EXISTS idx_agent_actions_active\n  ON agent_actions(agent_name, action_name) WHERE revoked_at IS NULL;\nCREATE INDEX IF NOT EXISTS idx_agent_actions_action ON agent_actions(action_name);\n\n-- schema_migrations: tracks which migration files have been applied to\n-- this DB. INFRA-MIGRATIONS card. Migration files live in\n-- .antiloki/migrations/ and run via system.migrate.run.\n-- Idempotent: each migration name is UNIQUE; re-running skips applied ones.\nCREATE TABLE IF NOT EXISTS schema_migrations (\n  id          INTEGER PRIMARY KEY AUTOINCREMENT,\n  name        TEXT    NOT NULL UNIQUE,\n  applied_at  TEXT    NOT NULL DEFAULT (datetime('now')),\n  applied_by  TEXT    NOT NULL,\n  sha256      TEXT    NOT NULL,\n  notes       TEXT\n);\n\n-- sacred_timeline + its timeline_with_commits view are GONE from main\n-- (FEAT-TIMELINE-RELOCATION): the table lives in the attached 'timeline'\n-- DB (TIMELINE_SCHEMA), and a view cannot span attached DBs, so consumers\n-- inline the sacred_timeline ⋈ timeline_commits join (see card-html.mjs).\n\n-- workflows: declarative compositions of actions. A workflow is \"1+\n-- actions, shared goal, invocable as one dispatch\". Separate table from\n-- actions to keep concerns clean (FEAT-WORKFLOWS-FOUNDATION).\nCREATE TABLE IF NOT EXISTS workflows (\n  id              INTEGER PRIMARY KEY AUTOINCREMENT,\n  name            TEXT    NOT NULL UNIQUE,\n  description     TEXT    NOT NULL,\n  owner_agent     TEXT    NOT NULL,\n  steps_json      TEXT    NOT NULL,\n  on_failure      TEXT    NOT NULL DEFAULT 'abort'\n    CHECK(on_failure IN ('abort','continue')),\n  created_at      TEXT    NOT NULL DEFAULT (datetime('now'))\n);\nCREATE INDEX IF NOT EXISTS idx_workflows_owner ON workflows(owner_agent);\n\n-- contracts: persisted output of contract.draft.auto. Single source of\n-- truth for the engineering spec that drives impl. Phases tracked via\n-- sacred_timeline (entity_type='contract', entity_id=slug) — no separate\n-- phases table. Supersede chain mirrors laws.laws pattern.\nCREATE TABLE IF NOT EXISTS contracts (\n  id                       INTEGER PRIMARY KEY AUTOINCREMENT,\n  slug                     TEXT    NOT NULL UNIQUE,\n  title                    TEXT    NOT NULL,\n  status                   TEXT    NOT NULL DEFAULT 'proposed'\n    CHECK (status IN ('proposed','pl_ratified','tl_approved','human_approved','impl','qa','done','rejected','superseded')),\n  template_kind            TEXT,\n  size                     TEXT\n    CHECK (size IS NULL OR size IN ('XS','S','M','L')),\n  complexity               INTEGER\n    CHECK (complexity IS NULL OR (complexity BETWEEN 1 AND 5)),\n  risk                     INTEGER\n    CHECK (risk IS NULL OR (risk BETWEEN 1 AND 5)),\n  tier                     TEXT\n    CHECK (tier IS NULL OR tier IN ('trivial','standard','high-risk')),\n  card_slug                TEXT,\n  files_touched_json       TEXT    NOT NULL DEFAULT '[]',\n  acceptance_json          TEXT    NOT NULL DEFAULT '[]',\n  naming_json              TEXT    NOT NULL DEFAULT '{}',\n  edge_cases_json          TEXT    NOT NULL DEFAULT '[]',\n  must_obey_json           TEXT    NOT NULL DEFAULT '[]',\n  out_of_scope_json        TEXT    NOT NULL DEFAULT '[]',\n  reference_artifacts_json TEXT    NOT NULL DEFAULT '[]',\n  briefing_md              TEXT,\n  base_sha                 TEXT,\n  current_attempt          INTEGER NOT NULL DEFAULT 1,\n  superseded_by            TEXT,\n  signed_by                TEXT,\n  signed_at                TEXT,\n  tl_briefing_md           TEXT,    -- TL prose connecting card → contract\n  tl_evaluation_md         TEXT,    -- TL judgment: template choice, edge risks\n  sandbox_path             TEXT,             -- relative to repo root; NULL = no sandbox yet\n  original_shas_json       TEXT NOT NULL DEFAULT '{}',  -- {relpath: sha256} captured at tl-sandbox-create time\n  -- EPIC-WORKTREE (ANTILOKI_WORKTREE, off by default): the git-worktree build\n  -- environment path (.antiloki/worktrees/<card>), set by git-manager.worktree.create,\n  -- cleared on merge. A FULL checkout (unlike the files-touched sandbox) so real\n  -- builds work for changes to a large repo. NULL = no worktree (use the sandbox).\n  worktree_path            TEXT,\n  microtasks_json          TEXT    NOT NULL DEFAULT '[]', -- TL-signed microtask plan (Alternative-2, migration 031)\n  goal_md                  TEXT,    -- DEV creative-direction guidance (migration 048)\n  dev_microtask_progress   INTEGER NOT NULL DEFAULT 0, -- per-microtask iteration cursor (migration 050)\n  last_qa_consumed_run_id  INTEGER, -- FK qa_runs.id — DEV's \"I've consumed up to this QA's suggestions\" cursor (migration 051)\n  rejection_reason_md      TEXT,    -- narrative captured on any rejection (TL/human/MAN) (migration 052)\n  failure_kind             TEXT,    -- soft enum: tl_empty_refusal, qa_acceptance_fail, human_*, man_revision_blocked (migration 052)\n  -- EPIC-QA-THINKS-DEV-EXECUTES (migration 061): counter capped by\n  -- TL_MAX_AMENDMENTS=2 in the state machine. After cap, amendment\n  -- suggestions stop dispatching to TL and route to human-escalate.\n  amendments_applied       INTEGER NOT NULL DEFAULT 0,\n  -- FEAT-PL-TL-HANDSHAKE-LOOP (migration 074): PL pushback counter, capped\n  -- by TL_MAX_PL_REVIEWS=2 in the state machine. After cap, MAN arbitrates.\n  pl_review_count          INTEGER NOT NULL DEFAULT 0,\n  pl_last_pushback_md      TEXT,\n  -- FEAT-MAN-DIGITAL-PRINT-COMPOSITION (migration 073): MAN's composed\n  -- git-commit message, stashed across the compose → commit steps. Mirrored\n  -- into the inline DDL 2026-07-11 (schema-drift canary) — a migration added\n  -- them but a fresh / :memory: DB was missing them.\n  digital_print_subject    TEXT,\n  digital_print_body       TEXT,\n  -- FIX-DRIVER-STAGE-FAILED-AUDITABLE (migration 123): last pipeline-stage\n  -- failure, stamped by pipeline-stage-record-failure under an audited\n  -- action so a failed stage lands on sacred_timeline instead of vanishing.\n  last_failure_kind        TEXT,\n  last_failure_md          TEXT,\n  last_failure_at          TEXT,\n  -- EPIC-AUTHORED-VS-GENERATED (migration 124): a contract's files split\n  -- into AUTHORED (TL writes the literal code as microtask.patches) and\n  -- GENERATED (produced by bootstrap_cmd inside the sandbox — node_modules,\n  -- lockfiles, dist). generated_paths are repo-relative path prefixes that\n  -- QA scope/diff and the authoring-coverage gate treat as allowed-without-\n  -- a-patch. bootstrap_cmd runs once with cwd=sandbox before acceptance.\n  bootstrap_cmd            TEXT,\n  generated_paths_json     TEXT    NOT NULL DEFAULT '[]',\n  -- EPIC-SHIFT-LEFT-BUILD-GATE: optional contract override for the deterministic\n  -- build/compile gate command run between DEV apply and QA (dev-build-gate.mjs).\n  -- NULL = derive a default (tsc --noEmit if tsconfig, npm run build if script).\n  build_cmd                TEXT,\n  -- FEAT-SLICED-RETRIES (migration 127): append-only re-author provenance —\n  -- one entry per tl.refine.microtasks pass: {attempt, ts, mode: 'full'|'sliced',\n  -- trigger, qa_run_id, kept_ids, replaced_ids, failing_ac_indices, why}.\n  -- Durable across QA windows (the state machine's reauthorAttempts resets\n  -- per failed qa_run) and across full re-authors (which discard the plan's\n  -- in-entry origin stamps).\n  refine_history_json      TEXT    NOT NULL DEFAULT '[]',\n  created_at               TEXT    NOT NULL DEFAULT (datetime('now')),\n  updated_at               TEXT    NOT NULL DEFAULT (datetime('now')),\n  FOREIGN KEY (card_slug)     REFERENCES cards(slug),\n  FOREIGN KEY (superseded_by) REFERENCES contracts(slug)\n);\nCREATE INDEX IF NOT EXISTS idx_contracts_status_tier ON contracts(status, tier);\nCREATE INDEX IF NOT EXISTS idx_contracts_card        ON contracts(card_slug);\nCREATE INDEX IF NOT EXISTS idx_contracts_active      ON contracts(slug) WHERE superseded_by IS NULL;\n\n-- runtime_events: every action + skill dispatch lands here. Visibility\n-- layer separate from sacred_timeline (audit chain). No JSON files, no\n-- external loggers — all observability is SQLite + render.\n-- RUNTIME-LOG-V1 card.\nCREATE TABLE IF NOT EXISTS runtime_events (\n  id              INTEGER PRIMARY KEY AUTOINCREMENT,\n  ts              TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),\n  parent_event_id INTEGER,\n  actor           TEXT    NOT NULL,\n  agent           TEXT,\n  action          TEXT,    -- the dispatched action (intent-named entry point)\n  skill           TEXT,    -- the atomic skill step within the action\n  duration_ms     REAL,\n  outcome         TEXT    NOT NULL\n    CHECK (outcome IN ('success','error','blocked','skipped','in_flight')),\n  error_code      TEXT,\n  context_json    TEXT,\n  -- FEAT-AUDIT-USER-GOAL-LINK (mig 033): correlation back to the interviewer\n  -- turn that triggered this dispatch chain. Threaded through action-run via\n  -- context.user_goal_id. NULL = caller did not declare a user goal.\n  user_goal_id    INTEGER REFERENCES interviewer_turns(id),\n  -- FEAT-DRIVER-GATE-SOURCE-THREAD (mig 035): WHICH entry point dispatched\n  -- this action — driver|mcp|cli|chat|test|unknown. Used by the driver\n  -- enforcement law to reject calls outside the driver loop unless allow-\n  -- listed or carrying a god signature. NULL on pre-mig-035 rows.\n  source          TEXT,\n  FOREIGN KEY (parent_event_id) REFERENCES runtime_events(id)\n);\nCREATE INDEX IF NOT EXISTS idx_runtime_events_ts      ON runtime_events(ts);\nCREATE INDEX IF NOT EXISTS idx_runtime_events_action  ON runtime_events(action);\nCREATE INDEX IF NOT EXISTS idx_runtime_events_problem ON runtime_events(outcome) WHERE outcome IN ('error','blocked');\n-- idx_runtime_events_user_goal lives in migration 033 (column-dependent).\n\n-- ── Interviewer tables (FEAT-INTERVIEWER-GATE) ─────────────────────\n-- Sole conversational entry point. Every user message produces a\n-- classified turn; mutations gate on confirmation.\n\nCREATE TABLE IF NOT EXISTS interviewer_sessions (\n  id                  INTEGER PRIMARY KEY AUTOINCREMENT,\n  started_at          TEXT    NOT NULL DEFAULT (datetime('now')),\n  last_active_at      TEXT    NOT NULL DEFAULT (datetime('now')),\n  user_identifier     TEXT,\n  status              TEXT    NOT NULL DEFAULT 'active'\n    CHECK (status IN ('active','idle','closed')),\n  ended_at            TEXT,\n  context_summary_md  TEXT\n);\n\nCREATE TABLE IF NOT EXISTS interviewer_turns (\n  id                          INTEGER PRIMARY KEY AUTOINCREMENT,\n  session_id                  INTEGER NOT NULL REFERENCES interviewer_sessions(id),\n  ts                          TEXT    NOT NULL DEFAULT (datetime('now')),\n  turn_index                  INTEGER NOT NULL,\n  user_text                   TEXT    NOT NULL,\n  classified_kind             TEXT    NOT NULL\n    CHECK (classified_kind IN ('read','propose','mutate','destructive','meta','clarify','autonomous','curate','investigate','start_work')),\n  classification_confidence   REAL\n    CHECK (classification_confidence IS NULL OR (classification_confidence >= 0 AND classification_confidence <= 1)),\n  classified_reason           TEXT,\n  proposed_actions_json       TEXT NOT NULL DEFAULT '[]',\n  confirmed                   INTEGER NOT NULL DEFAULT 0\n    CHECK (confirmed IN (0,1)),\n  dispatched_action_ids_json  TEXT,\n  interviewer_response_md     TEXT,\n  clarify_questionnaire_json  TEXT,  -- FEAT-INTERVIEWER-CONFIDENCE-SCREENING: screening fork (question + A/B/C options)\n  user_text_embedding         BLOB,  -- FEAT-CROSS-SESSION-RAG: Float32Array bytes\n  -- COCKPIT Wave 3/7 (model picker + debug lens): which model answered this turn + the\n  -- triage ai-call's id/tier/cost/latency. The chat renders a model badge + a debug chip\n  -- that opens the AI-call inspector. All NULL on AI-less turns (greeting / destructive /\n  -- pl-clarify floors). ai_call_id is a cross-DB ref → brain.ai_calls.id (no FK by convention).\n  model_id                    TEXT,\n  ai_call_id                  INTEGER,\n  ai_tier                     TEXT,\n  ai_cost_usd                 REAL,\n  ai_duration_ms              INTEGER,\n  ai_tokens_in                INTEGER,\n  ai_tokens_out               INTEGER,\n  -- WIDGET DURABILITY: the presenter's view_intent + view_data (the inline widgets — improvements article,\n  -- diagram, board, table …) persisted so a reloaded session RE-renders them instead of losing them (were\n  -- ephemeral, live-turn-only). NULL on prose-only turns. deriveWidgets reads view_intent + view_data_json.\n  view_intent                 TEXT,\n  view_data_json              TEXT,\n  ai_telemetry_json           TEXT,  -- migration 164: full per-call AI telemetry for the turn (cost/tokens/#calls)\n  offered_widgets_json        TEXT,  -- migration 171: DETERMINISTIC widget offers (buttons) — see interviewer-widget-offers\n  sources_json                TEXT,  -- migration 172 (c1): grounding sources [{kind,path}] from smart-context-bundle → the answer's \"Sources\" list\n  UNIQUE(session_id, turn_index)\n);\n\nCREATE INDEX IF NOT EXISTS idx_interviewer_turns_session ON interviewer_turns(session_id);\nCREATE INDEX IF NOT EXISTS idx_interviewer_turns_kind    ON interviewer_turns(classified_kind);\n\n-- STUDIO RESULT DURABILITY (operator 2026-07-15: \"widgets and artifacts should be part of the\n-- chat history when generated, not loosing them on reload\"). A Studio generation anchors to the\n-- turn whose conversation grounded it; sessionTurns attaches these rows and deriveWidgets\n-- re-renders them. Not an audited entity (like interviewer_turns itself).\nCREATE TABLE IF NOT EXISTS interviewer_turn_widgets (\n  id           INTEGER PRIMARY KEY AUTOINCREMENT,\n  turn_id      INTEGER NOT NULL REFERENCES interviewer_turns(id),\n  type         TEXT    NOT NULL CHECK (type IN ('widget','artifact')),\n  kind         TEXT    NOT NULL,\n  payload_json TEXT    NOT NULL,\n  created_at   TEXT    NOT NULL DEFAULT (datetime('now'))\n);\nCREATE INDEX IF NOT EXISTS idx_interviewer_turn_widgets_turn ON interviewer_turn_widgets(turn_id);\n\n-- SESSION-SCOPED widgets/artefacts + pinned context (operator 2026-07-25: \"save the widgets and context\n-- in the sessions so we can retrieve ALWAYS\"). Unlike interviewer_turn_widgets these belong to the\n-- SESSION and need NO turn — so anything generated in a fresh, message-less chat still persists (the \"New\n-- chat\" now creates the session eagerly). turn_id is an OPTIONAL timeline hint (render order). kind\n-- 'session-context' carries the pinned @ refs as {refs:[...]}. Append-only, non-audited (like turns).\nCREATE TABLE IF NOT EXISTS interviewer_session_widgets (\n  id           INTEGER PRIMARY KEY AUTOINCREMENT,\n  session_id   INTEGER NOT NULL REFERENCES interviewer_sessions(id),\n  turn_id      INTEGER REFERENCES interviewer_turns(id),\n  type         TEXT    NOT NULL CHECK (type IN ('widget','artifact')),\n  kind         TEXT    NOT NULL,\n  payload_json TEXT    NOT NULL,\n  created_at   TEXT    NOT NULL DEFAULT (datetime('now'))\n);\nCREATE INDEX IF NOT EXISTS idx_interviewer_session_widgets_session ON interviewer_session_widgets(session_id);\n\n-- FEAT-CROSS-SESSION-RAG (Phase 4): episodic memory over user inputs.\n-- Stored as Float32Array bytes (768 dims for bge-base = 3KB per row).\n-- Migration 20260520-010 adds this column on existing DBs.\n\n-- ── PL session tables (PL-V2-SESSION-SCHEMA card #69) ────────────────\n-- Multi-step elicit → research → decompose → tune → propose → approve.\n-- No JSON columns; every structured datum is a row.\n\nCREATE TABLE IF NOT EXISTS pl_sessions (\n  id                    INTEGER PRIMARY KEY AUTOINCREMENT,\n  raw_intent            TEXT    NOT NULL,\n  status                TEXT    NOT NULL DEFAULT 'clarifying'\n    CHECK (status IN ('clarifying','researching','deciding_split','tuning','awaiting_approval','done','abandoned')),\n  started_by            TEXT    NOT NULL,\n  budget_usd            REAL    NOT NULL DEFAULT 0.05,\n  spent_usd             REAL    NOT NULL DEFAULT 0.0,\n  approved_card_slug    TEXT,\n  parent_session_id     INTEGER REFERENCES pl_sessions(id),  -- recursion (decompose → child sessions)\n  created_at            TEXT    NOT NULL DEFAULT (datetime('now')),\n  updated_at            TEXT    NOT NULL DEFAULT (datetime('now')),\n  FOREIGN KEY (approved_card_slug) REFERENCES cards(slug)\n);\nCREATE INDEX IF NOT EXISTS idx_pl_sessions_status ON pl_sessions(status);\nCREATE INDEX IF NOT EXISTS idx_pl_sessions_parent ON pl_sessions(parent_session_id);\n\nCREATE TABLE IF NOT EXISTS pl_questions (\n  id              INTEGER PRIMARY KEY AUTOINCREMENT,\n  session_id      INTEGER NOT NULL REFERENCES pl_sessions(id),\n  step            TEXT    NOT NULL CHECK (step IN ('clarify','research','decompose','tune')),\n  question_md     TEXT    NOT NULL,\n  allows_writein  INTEGER NOT NULL DEFAULT 1,\n  order_index     INTEGER NOT NULL,\n  ai_call_id      INTEGER,  -- cross-DB → brain.ai_calls.id (no FK)\n  created_at      TEXT    NOT NULL DEFAULT (datetime('now'))\n);\nCREATE INDEX IF NOT EXISTS idx_pl_questions_session ON pl_questions(session_id, step, order_index);\n\nCREATE TABLE IF NOT EXISTS pl_question_options (\n  id              INTEGER PRIMARY KEY AUTOINCREMENT,\n  question_id     INTEGER NOT NULL REFERENCES pl_questions(id),\n  option_md       TEXT    NOT NULL,\n  order_index     INTEGER NOT NULL\n);\nCREATE INDEX IF NOT EXISTS idx_pl_question_options_q ON pl_question_options(question_id, order_index);\n\nCREATE TABLE IF NOT EXISTS pl_answers (\n  id                  INTEGER PRIMARY KEY AUTOINCREMENT,\n  question_id         INTEGER NOT NULL UNIQUE REFERENCES pl_questions(id),\n  selected_option_id  INTEGER REFERENCES pl_question_options(id),\n  writein_md          TEXT,\n  answered_by         TEXT    NOT NULL,\n  answered_at         TEXT    NOT NULL DEFAULT (datetime('now')),\n  CHECK (selected_option_id IS NOT NULL OR writein_md IS NOT NULL)\n);\n\n-- Research findings (one row per finding)\nCREATE TABLE IF NOT EXISTS pl_research_findings (\n  id              INTEGER PRIMARY KEY AUTOINCREMENT,\n  session_id      INTEGER NOT NULL REFERENCES pl_sessions(id),\n  finding_type    TEXT    NOT NULL\n    CHECK (finding_type IN ('similar-card','correction-memory','applicable-law','knowledge-extract')),\n  target_ref      TEXT    NOT NULL,\n  relevance_score REAL,\n  why_relevant_md TEXT,\n  order_index     INTEGER NOT NULL,\n  ai_call_id      INTEGER,\n  created_at      TEXT    NOT NULL DEFAULT (datetime('now'))\n);\nCREATE INDEX IF NOT EXISTS idx_pl_research_session ON pl_research_findings(session_id, finding_type);\n\n-- Decomposition\nCREATE TABLE IF NOT EXISTS pl_decompositions (\n  id              INTEGER PRIMARY KEY AUTOINCREMENT,\n  session_id      INTEGER NOT NULL UNIQUE REFERENCES pl_sessions(id),\n  is_atomic       INTEGER NOT NULL,\n  reasoning_md    TEXT    NOT NULL,\n  ai_call_id      INTEGER,\n  created_at      TEXT    NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS pl_decomposition_children (\n  id                INTEGER PRIMARY KEY AUTOINCREMENT,\n  decomposition_id  INTEGER NOT NULL REFERENCES pl_decompositions(id),\n  title             TEXT    NOT NULL,\n  intent_md         TEXT    NOT NULL,\n  size_estimate     TEXT    CHECK (size_estimate IS NULL OR size_estimate IN ('XS','S','M','L')),\n  why_separate_md   TEXT,\n  order_index       INTEGER NOT NULL,\n  child_session_id  INTEGER REFERENCES pl_sessions(id)\n);\n\n-- Proposed card awaiting user approval\n-- PR TEST SUITE (operator 2026-07-05): the PR is an ISOLATED TEST ENVIRONMENT — the\n-- worktree + a deterministic suite sliced from the card's acceptance. Every run persists\n-- its checks WITH PROOFS; human verdicts overlay machine ones (the tagging strategy:\n-- machine argues, human rules). suggestion_md holds AI-drafted unit tests the operator\n-- can propose as a card via the interviewer (cards stay human-ratified).\nCREATE TABLE IF NOT EXISTS pr_test_runs (\n  id            INTEGER PRIMARY KEY AUTOINCREMENT,\n  ref_slug      TEXT NOT NULL,\n  branch        TEXT,\n  worktree_path TEXT,\n  started_at    TEXT NOT NULL DEFAULT (datetime('now')),\n  duration_ms   INTEGER,\n  summary_json  TEXT,\n  checks_json   TEXT,\n  suggestion_md TEXT\n);\nCREATE INDEX IF NOT EXISTS idx_pr_test_runs_ref ON pr_test_runs(ref_slug);\n\nCREATE TABLE IF NOT EXISTS pl_proposed_cards (\n  id                  INTEGER PRIMARY KEY AUTOINCREMENT,\n  session_id          INTEGER NOT NULL REFERENCES pl_sessions(id),\n  slug_suggestion     TEXT    NOT NULL,\n  title               TEXT    NOT NULL,\n  body_md             TEXT    NOT NULL,\n  template_kind       TEXT,\n  priority            INTEGER CHECK (priority IS NULL OR (priority BETWEEN 1 AND 5)),\n  size_estimate       TEXT    CHECK (size_estimate IS NULL OR size_estimate IN ('XS','S','M','L')),\n  status              TEXT    NOT NULL DEFAULT 'awaiting_approval'\n    CHECK (status IN ('awaiting_approval','approved','rejected','superseded')),\n  approved_by         TEXT,\n  approved_at         TEXT,\n  rejection_reason_md TEXT,\n  ai_call_id          INTEGER,\n  created_at          TEXT    NOT NULL DEFAULT (datetime('now'))\n);\nCREATE INDEX IF NOT EXISTS idx_pl_proposed_cards_status ON pl_proposed_cards(status);\n\n-- ── Agent stages (AGENT-STAGES-SCHEMA card #78) ──────────────────────\n-- Every persona-style agent has stages (read_contract, implement, etc.)\n-- Each stage declares which actions it uses, in what order, with what\n-- invocation pattern. MAN agent reads this to detect drift between\n-- declared workflow and actual runtime_events.\nCREATE TABLE IF NOT EXISTS agent_stages (\n  id               INTEGER PRIMARY KEY AUTOINCREMENT,\n  agent_name       TEXT    NOT NULL,\n  stage_name       TEXT    NOT NULL,\n  order_index      INTEGER NOT NULL,\n  description_md   TEXT    NOT NULL,\n  entry_signal     TEXT,   -- e.g. 'pl_session.status=clarifying' (free-text;\n                          -- canonical signals enforced by stage-validate action)\n  exit_signal      TEXT,\n  -- EPIC-DRIVER-BULLETPROOF WS-1C: a stage row is also the SST for the FE\n  -- pipeline view. pipeline_order is the global happy-path index (distinct\n  -- from per-agent order_index); fe_group is the coarse human-friendly bucket\n  -- the waterfall renders (plan|build|verify) so the FE derives its simplified\n  -- 3-stage view from this table instead of a hardcoded list that drifts.\n  pipeline_order   INTEGER,\n  fe_group         TEXT,\n  created_at       TEXT    NOT NULL DEFAULT (datetime('now')),\n  UNIQUE (agent_name, stage_name),\n  FOREIGN KEY (agent_name) REFERENCES agents(name)\n);\nCREATE INDEX IF NOT EXISTS idx_agent_stages_agent ON agent_stages(agent_name, order_index);\n\nCREATE TABLE IF NOT EXISTS agent_stage_actions (\n  id                  INTEGER PRIMARY KEY AUTOINCREMENT,\n  agent_stage_id      INTEGER NOT NULL REFERENCES agent_stages(id),\n  action_name         TEXT    NOT NULL,\n  order_index         INTEGER NOT NULL,\n  is_optional         INTEGER NOT NULL DEFAULT 0,\n  invocation_pattern  TEXT    NOT NULL\n    CHECK (invocation_pattern IN ('always','conditional','manual')),\n  rationale_md        TEXT,\n  UNIQUE (agent_stage_id, action_name, order_index),\n  FOREIGN KEY (action_name) REFERENCES actions(name)\n);\nCREATE INDEX IF NOT EXISTS idx_agent_stage_actions_stage ON agent_stage_actions(agent_stage_id, order_index);\n\n-- ── QA runs (persistent acceptance results) ──────────────────────────\n-- Every qa.acceptance.run invocation persists a row + one row per AC item.\n-- Lets us audit/render QA history per contract without re-running.\nCREATE TABLE IF NOT EXISTS qa_runs (\n  id              INTEGER PRIMARY KEY AUTOINCREMENT,\n  contract_slug   TEXT    NOT NULL,\n  ts              TEXT    NOT NULL DEFAULT (datetime('now')),\n  verifier        TEXT    NOT NULL,\n  scope_passed    INTEGER,  -- nullable: not all runs include scope\n  acceptance_pass INTEGER,  -- count of AC items that passed\n  acceptance_fail INTEGER,\n  all_passed      INTEGER NOT NULL,\n  notes_md        TEXT,\n  -- FEAT-QA-DEV-FEEDBACK-LOOP: AI-generated narrative + structured\n  -- microtasks DEV should append to its plan when QA fails. Persisted\n  -- per-run so the remediation chain is auditable. Null on passing runs.\n  feedback_md     TEXT,\n  suggested_microtasks_json TEXT,\n  -- EPIC-QA-THINKS-DEV-EXECUTES (migration 061): when QA cannot produce\n  -- a structured remediation plan (e.g. flaky external infra), persist\n  -- the reason. State machine reads this to route to human instead of\n  -- retrying with empty suggestions.\n  escalation_reason TEXT\n);\nCREATE INDEX IF NOT EXISTS idx_qa_runs_contract ON qa_runs(contract_slug, ts DESC);\n\nCREATE TABLE IF NOT EXISTS qa_run_results (\n  id              INTEGER PRIMARY KEY AUTOINCREMENT,\n  qa_run_id       INTEGER NOT NULL REFERENCES qa_runs(id),\n  ac_index        INTEGER NOT NULL,\n  kind            TEXT    NOT NULL,\n  passed          INTEGER NOT NULL,\n  evidence_md     TEXT\n);\nCREATE INDEX IF NOT EXISTS idx_qa_run_results_run ON qa_run_results(qa_run_id, ac_index);\n\n-- EPIC-SHIFT-LEFT-BUILD-GATE: deterministic build/compile gate between DEV\n-- apply and QA. dev-build-gate.mjs runs the contract's build_cmd against the\n-- sandbox and writes one row per gate run. Derived artifact (like qa_runs) —\n-- written by direct INSERT from the skill, NOT audited. Mirrored here so\n-- in-memory test DBs get the schema without running migrations.\nCREATE TABLE IF NOT EXISTS build_gate_runs (\n  id              INTEGER PRIMARY KEY AUTOINCREMENT,\n  contract_slug   TEXT    NOT NULL,\n  passed          INTEGER NOT NULL,\n  skipped         INTEGER NOT NULL DEFAULT 0,  -- 1 = no build cmd resolvable (auto-pass)\n  build_cmd       TEXT,                        -- the command actually run (NULL when skipped)\n  evidence_md     TEXT,                        -- full stdout+stderr (un-truncated budget)\n  applied_at      TEXT,                        -- the dev.implement.code tick this gate ran against\n  snippets_hash   TEXT,                        -- FIX-V2-BUILD-GATE-FRESHNESS: content identity of the snippets this gate built (v2)\n  ts              TEXT    NOT NULL DEFAULT (datetime('now'))\n);\nCREATE INDEX IF NOT EXISTS idx_build_gate_runs_contract ON build_gate_runs(contract_slug, ts DESC);\n\n-- LIVE GATE TELEMETRY (operator 2026-07-05: \"mirror the terminal on the build gate\"):\n-- long-running gates (build, deps install) stream their stdout/stderr here CHUNK BY CHUNK\n-- while still blocking the tick; the FE polls after=<seq> and renders a live terminal.\n-- Ephemeral by nature — rows for a contract are cleared when its next stream starts.\nCREATE TABLE IF NOT EXISTS build_gate_live (\n  id            INTEGER PRIMARY KEY AUTOINCREMENT,\n  contract_slug TEXT NOT NULL,\n  phase         TEXT NOT NULL DEFAULT 'build',   -- build | install | test\n  seq           INTEGER NOT NULL,\n  chunk         TEXT,\n  done          INTEGER NOT NULL DEFAULT 0,      -- final row per stream sets 1\n  ts            TEXT NOT NULL DEFAULT (datetime('now'))\n);\nCREATE INDEX IF NOT EXISTS idx_build_gate_live ON build_gate_live(contract_slug, id);\n\n-- SNIPPET LINT RUNS (operator 2026-07-05: \"lint snippets rung stays grey\"): the verdict\n-- snippetLint already computes, PERSISTED where the waterfall can read it — one row per\n-- authoring pass (green/red rung + violations on expand).\nCREATE TABLE IF NOT EXISTS snippet_lint_runs (\n  id            INTEGER PRIMARY KEY AUTOINCREMENT,\n  contract_slug TEXT NOT NULL,\n  blueprint_id  INTEGER,\n  passed        INTEGER NOT NULL,\n  issues_json   TEXT,\n  missing_json  TEXT,\n  ts            TEXT NOT NULL DEFAULT (datetime('now'))\n);\nCREATE INDEX IF NOT EXISTS idx_snippet_lint_runs ON snippet_lint_runs(contract_slug, id DESC);\n\n-- LINT GATE RUNS (operator 2026-07-06: \"lints ignored at the driver\" — a PASS with\n-- advisory findings wrote NOTHING anywhere, so 'PASS (1 non-blocking finding)' was\n-- unanswerable). EVERY lint-gate run persists here — pass or red, both modes — so the\n-- waterfall lint rungs can show the verdict AND the advisories that rode with it.\nCREATE TABLE IF NOT EXISTS lint_gate_runs (\n  id            INTEGER PRIMARY KEY AUTOINCREMENT,\n  contract_slug TEXT NOT NULL,\n  mode          TEXT NOT NULL,            -- design | snippets\n  blueprint_id  INTEGER,\n  version       INTEGER,\n  passed        INTEGER NOT NULL,\n  findings_json TEXT NOT NULL DEFAULT '[]',\n  duration_ms   INTEGER,\n  ts            TEXT NOT NULL DEFAULT (datetime('now'))\n);\nCREATE INDEX IF NOT EXISTS idx_lint_gate_runs ON lint_gate_runs(contract_slug, id DESC);\n\n-- TEST GATE RUNS (operator 2026-07-06: \"a gate after the build gate for test\"). Mirrors\n-- build_gate_runs: the workspace's test script (scripts registry → package.json) runs in\n-- the worktree after a GREEN build; no test script = skip (auto-pass, never false-blocks).\nCREATE TABLE IF NOT EXISTS test_gate_runs (\n  id            INTEGER PRIMARY KEY AUTOINCREMENT,\n  contract_slug TEXT NOT NULL,\n  passed        INTEGER NOT NULL,\n  skipped       INTEGER DEFAULT 0,\n  test_cmd      TEXT,\n  evidence_md   TEXT,\n  snippets_hash TEXT,\n  duration_ms   INTEGER,\n  phase         TEXT NOT NULL DEFAULT 'after',  -- baseline (pre-apply) | after (post-build)\n  ts            TEXT NOT NULL DEFAULT (datetime('now'))\n);\nCREATE INDEX IF NOT EXISTS idx_test_gate_runs ON test_gate_runs(contract_slug, id DESC);\n\n-- EPIC-SHIFT-LEFT-QA: QA #1 contract review (thinking gate) between PL review\n-- and DEV. qa-contract-review.mjs reads the contract + microtasks + literal\n-- patches and records one verdict row per review. Derived artifact (like\n-- build_gate_runs / qa_runs) — written by direct INSERT from the skill, NOT\n-- audited. Mirrored here so in-memory test DBs get the schema without migrations.\nCREATE TABLE IF NOT EXISTS contract_qa_reviews (\n  id              INTEGER PRIMARY KEY AUTOINCREMENT,\n  contract_slug   TEXT    NOT NULL,\n  passed          INTEGER NOT NULL,            -- 1 = pass (good enough for DEV), 0 = fail (bounce to TL)\n  verdict         TEXT    NOT NULL,            -- 'pass' | 'fail'\n  findings_md     TEXT,                        -- QA narrative (cites the offending microtask/file/snippet)\n  issues_json     TEXT,                        -- [{severity, microtask_id, file, problem, fix_hint}]\n  reviewer        TEXT,                        -- e.g. 'driver:auto'\n  -- FIX-QA-FINDINGS-ROUTE-TO-RIGHT-ARTIFACT (migration 131): where the fix\n  -- belongs. 'microtasks' = TL re-authoring can fix it (bounded retry loop);\n  -- 'contract' = the contract itself is defective (impossible acceptance,\n  -- wrong scope) and the driver escalates to the operator immediately.\n  failure_target  TEXT    NOT NULL DEFAULT 'microtasks'\n    CHECK (failure_target IN ('microtasks', 'contract')),\n  -- TL-REFINE-STAGE-SPLIT (migration 133): 'plan' = decomposition review\n  -- (defs only, pre-authoring); 'full' = patch-level review. NULL on\n  -- legacy rows = 'full'. Plain TEXT (no CHECK rebuild on the live table).\n  review_mode     TEXT,\n  ts              TEXT    NOT NULL DEFAULT (datetime('now'))\n);\nCREATE INDEX IF NOT EXISTS idx_contract_qa_reviews_contract ON contract_qa_reviews(contract_slug, ts DESC);\n\n-- FEAT-REJECTION-RECOVERY-AND-MAN-AUDIT (migration 052):\n-- Deterministic per-phase audit records written by MAN at the two\n-- contract milestones (contract_signed + qa_passed) plus revision_audit\n-- (gate for re-signed contracts after a rejection-driven re-draft).\nCREATE TABLE IF NOT EXISTS man_reports (\n  id              INTEGER PRIMARY KEY AUTOINCREMENT,\n  contract_slug   TEXT    NOT NULL,\n  phase           TEXT    NOT NULL CHECK (phase IN ('contract_signed','qa_passed','revision_audit')),\n  ts              TEXT    NOT NULL DEFAULT (datetime('now')),\n  verdict         TEXT    NOT NULL CHECK (verdict IN ('approved','flagged','blocked')),\n  metrics_json    TEXT,\n  criteria_json   TEXT,\n  what_happened_md TEXT,\n  lessons_md      TEXT,\n  FOREIGN KEY (contract_slug) REFERENCES contracts(slug)\n);\nCREATE INDEX IF NOT EXISTS idx_man_reports_contract     ON man_reports(contract_slug, ts DESC);\nCREATE INDEX IF NOT EXISTS idx_man_reports_phase_verdict ON man_reports(phase, verdict);\n\n-- EPIC-CARD-REVIEW-BLUEPRINT (migration 109): one immutable frozen review\n-- snapshot per (card, contract, attempt) — the diff + per-AC anchors +\n-- behavioral verdicts + assembled narrative. Derived artifact (like\n-- man_reports), written directly by its generator skill. Mirrored here so\n-- in-memory test DBs get the schema without running migrations.\nCREATE TABLE IF NOT EXISTS card_review_blueprints (\n  id              INTEGER PRIMARY KEY AUTOINCREMENT,\n  card_slug       TEXT    NOT NULL,\n  contract_slug   TEXT    NOT NULL,\n  attempt         INTEGER NOT NULL DEFAULT 1,\n  qa_run_id       INTEGER,\n  base_sha        TEXT,\n  head_sha        TEXT,\n  diff_source     TEXT    CHECK (diff_source IS NULL OR diff_source IN ('sandbox','git')),\n  diff_json       TEXT    NOT NULL DEFAULT '[]',\n  anchors_json    TEXT    NOT NULL DEFAULT '[]',\n  behavioral_json TEXT    NOT NULL DEFAULT '[]',\n  narrative_md    TEXT    NOT NULL DEFAULT '',\n  verdict         TEXT,\n  generated_by    TEXT    NOT NULL DEFAULT 'unknown',\n  generated_at    TEXT    NOT NULL DEFAULT (datetime('now')),\n  UNIQUE (card_slug, contract_slug, attempt)\n);\nCREATE INDEX IF NOT EXISTS idx_review_blueprints_card\n  ON card_review_blueprints (card_slug, generated_at DESC);\n\n-- EPIC-SWARM (ANTILOKI_SWARM, default-on; =off to disable): the blueprint NUCLEUS — the typed\n-- dataflow manifest a contract's high-tier design produces and every low-tier\n-- block reads its own slice of. Append-only with superseded_by versioning (like\n-- memories/laws). manifest_json holds the full graph (blocks + bindings);\n-- deterministic manifest-lint records its verdict in lint_passed/lint_json.\n-- Purely additive: with the flag off nothing reads or writes this table.\nCREATE TABLE IF NOT EXISTS swarm_manifests (\n  id            INTEGER PRIMARY KEY AUTOINCREMENT,\n  contract_slug TEXT    NOT NULL,\n  version       INTEGER NOT NULL DEFAULT 1,\n  goal          TEXT,\n  manifest_json TEXT    NOT NULL DEFAULT '{}',\n  lint_passed   INTEGER NOT NULL DEFAULT 0,\n  lint_json     TEXT    NOT NULL DEFAULT '{}',\n  created_by    TEXT    NOT NULL DEFAULT 'unknown',\n  created_at    TEXT    NOT NULL DEFAULT (datetime('now')),\n  superseded_by INTEGER REFERENCES swarm_manifests(id)\n);\nCREATE INDEX IF NOT EXISTS idx_swarm_manifests_active\n  ON swarm_manifests (contract_slug) WHERE superseded_by IS NULL;\n\n-- EPIC-SWARM: the \"session case\" — one rendered adversarial plea per\n-- (contract, microtask scope, attempt). The prosecutor/defender arguments are\n-- validated (argument-links) + transcluded (session-case) into document_md, the\n-- single document the judge reads. verdict is the judge's call (NULL = pending).\n-- microtask_id '' = contract-level scope (kept NOT NULL so UNIQUE is stable).\nCREATE TABLE IF NOT EXISTS swarm_session_cases (\n  id               INTEGER PRIMARY KEY AUTOINCREMENT,\n  contract_slug    TEXT    NOT NULL,\n  microtask_id     TEXT    NOT NULL DEFAULT '',\n  attempt          INTEGER NOT NULL DEFAULT 1,\n  document_md      TEXT    NOT NULL DEFAULT '',\n  summary_json     TEXT    NOT NULL DEFAULT '{}',\n  prosecution_json TEXT    NOT NULL DEFAULT '[]',\n  defense_json     TEXT    NOT NULL DEFAULT '[]',\n  verdict          TEXT,\n  judge_reviewer   TEXT,\n  created_at       TEXT    NOT NULL DEFAULT (datetime('now')),\n  UNIQUE (contract_slug, microtask_id, attempt)\n);\nCREATE INDEX IF NOT EXISTS idx_swarm_session_cases_contract\n  ON swarm_session_cases (contract_slug, created_at DESC);\n\n-- EPIC-SWARM: the per-file authored-code store (the \"shell\"). One row per block\n-- per manifest version — the LOW author swarm writes each file's content here,\n-- and the deterministic composition-check stamps compose_passed. Kept SEPARATE\n-- from the legacy contracts.microtasks_json path on purpose (operator decision:\n-- new swarm store, max isolation — the legacy author→sign→QA→build path stays\n-- pristine; swarm-aware branches read from here). Flag-gated.\nCREATE TABLE IF NOT EXISTS swarm_blocks (\n  id             INTEGER PRIMARY KEY AUTOINCREMENT,\n  contract_slug  TEXT    NOT NULL,\n  manifest_id    INTEGER,\n  block_id       TEXT    NOT NULL,\n  file           TEXT    NOT NULL,\n  content        TEXT,\n  authored_by    TEXT,\n  compose_passed INTEGER,\n  compose_json   TEXT,\n  authored_at    TEXT    NOT NULL DEFAULT (datetime('now')),\n  UNIQUE (manifest_id, block_id)\n);\nCREATE INDEX IF NOT EXISTS idx_swarm_blocks_contract ON swarm_blocks (contract_slug, authored_at DESC);\n\n-- ── PIPELINE V2 (docs/pipeline-v2.md · blueprint-spine.md · contract-table.md) ──\n-- Additive + JSON-blob; consumed only when ANTILOKI_PIPELINE_V2 wires the new stages.\n-- Unused by v1, so creating them disturbs nothing.\nCREATE TABLE IF NOT EXISTS pl_screenings (\n  id             INTEGER PRIMARY KEY AUTOINCREMENT,\n  card_slug      TEXT    NOT NULL,\n  screening_json TEXT    NOT NULL DEFAULT '{}',   -- enriched context + acceptance S-tasks\n  lint_passed    INTEGER NOT NULL DEFAULT 0,\n  lint_json      TEXT    NOT NULL DEFAULT '{}',\n  created_by     TEXT    NOT NULL DEFAULT 'unknown',\n  created_at     TEXT    NOT NULL DEFAULT (datetime('now'))\n);\nCREATE INDEX IF NOT EXISTS idx_pl_screenings_card ON pl_screenings (card_slug, created_at DESC);\n\nCREATE TABLE IF NOT EXISTS blueprints (\n  id            INTEGER PRIMARY KEY AUTOINCREMENT,\n  contract_slug TEXT    NOT NULL,\n  version       INTEGER NOT NULL DEFAULT 1,\n  blueprint_json TEXT   NOT NULL DEFAULT '{}',    -- recursive blocks + bindings\n  lint_passed   INTEGER NOT NULL DEFAULT 0,\n  lint_json     TEXT    NOT NULL DEFAULT '{}',\n  created_by    TEXT    NOT NULL DEFAULT 'unknown',\n  created_at    TEXT    NOT NULL DEFAULT (datetime('now')),\n  superseded_by INTEGER REFERENCES blueprints(id)\n);\nCREATE INDEX IF NOT EXISTS idx_blueprints_active ON blueprints (contract_slug) WHERE superseded_by IS NULL;\n\nCREATE TABLE IF NOT EXISTS blueprint_snippets (\n  id           INTEGER PRIMARY KEY AUTOINCREMENT,\n  blueprint_id INTEGER NOT NULL,\n  block_id     TEXT    NOT NULL,\n  code         TEXT,\n  imports_json TEXT,\n  exports_json TEXT,\n  authored_by  TEXT,\n  authored_at  TEXT    NOT NULL DEFAULT (datetime('now')),\n  UNIQUE (blueprint_id, block_id)\n);\nCREATE INDEX IF NOT EXISTS idx_blueprint_snippets ON blueprint_snippets (blueprint_id);\n\n-- code_onboard_jobs LIVES HERE, NOT IN THE CODE DB, even though every other code_* table is a\n-- code-schema table. It is rebuild BOOKKEEPING, not atlas data, and the distinction is load-bearing:\n-- a staged rebuild re-points the `code` schema at code.rebuild.sqlite so no half-built atlas is ever\n-- served. While that is in force, a job row written through `code` lands in the STAGING file, where\n-- the BE polling the live DB can never see it — so every rebuild's row sat frozen at 'queued' and\n-- the status poller's zombie-heal eventually declared a perfectly healthy job dead ('stale: the BE\n-- restarted mid-onboard' — it had not). The runner's own header always said the live DB is touched\n-- for the job row; putting the table in `main` is what makes that true.\n--\n-- `main` is state.sqlite, and SQLite resolves an unqualified name against main BEFORE any attached\n-- schema, so every existing `FROM code_onboard_jobs` query now reads this copy with no rewrite. The\n-- legacy copy in code.sqlite is left alone: harmless, unreachable, and deleting it would be a\n-- destructive migration for rows that are transient progress anyway.\nCREATE TABLE IF NOT EXISTS code_onboard_jobs (\n  job_id       TEXT PRIMARY KEY,\n  root         TEXT NOT NULL,\n  phase        TEXT NOT NULL DEFAULT 'queued',\n  status       TEXT NOT NULL DEFAULT 'running',\n  profile_json TEXT,\n  error        TEXT,\n  detail       TEXT,\n  created_at   TEXT NOT NULL DEFAULT (datetime('now')),\n  updated_at   TEXT NOT NULL DEFAULT (datetime('now'))\n);\n""#).expect("STATE_SCHEMA: embedded JSON is valid by construction")
});

pub static MEMORY_SCHEMA: LazyLock<Value> = LazyLock::new(|| {
    serde_json::from_str(r#""\n-- All memory tables live in the attached \"memory\" database.\n-- FK to sacred_timeline is intentionally omitted (cross-DB FKs unsupported).\nCREATE TABLE IF NOT EXISTS memory.memories (\n  id              INTEGER PRIMARY KEY AUTOINCREMENT,\n  type            TEXT    NOT NULL,\n  title           TEXT    NOT NULL,\n  situation       TEXT    NOT NULL,\n  guidance        TEXT    NOT NULL,\n  naive_response  TEXT,\n  rationale       TEXT,\n  tags_json       TEXT    NOT NULL DEFAULT '[]',\n  source_card     TEXT,\n  source_event    INTEGER,\n  source_session  TEXT,\n  confidence      REAL    NOT NULL DEFAULT 0.5,\n  validated       INTEGER NOT NULL DEFAULT 0,\n  superseded_by   INTEGER,\n  -- FEAT-MEMORY-AGENT-SCOPED: which agent owns this memory. NULL = global\n  -- (current default — backward compat). Per-agent scoping lets pl remember\n  -- product decisions, dev remember code patterns, qa remember failures.\n  agent_slug      TEXT,\n  created_at      TEXT    NOT NULL DEFAULT (datetime('now')),\n  created_by      TEXT    NOT NULL,\n  CHECK (type IN ('lesson', 'preference', 'decision', 'reference', 'correction', 'narrative')),\n  CHECK (confidence >= 0.0 AND confidence <= 1.0),\n  CHECK (validated IN (0, 1)),\n  FOREIGN KEY (superseded_by) REFERENCES memories(id)\n);\n\nCREATE INDEX IF NOT EXISTS memory.idx_memories_type      ON memories(type);\nCREATE INDEX IF NOT EXISTS memory.idx_memories_validated ON memories(validated);\nCREATE INDEX IF NOT EXISTS memory.idx_memories_source    ON memories(source_card);\n-- agent_slug index created defensively in JS after STATE_SCHEMA (column\n-- may be absent on pre-024 persisted DBs).\n\n-- NOTE: views removed in v0.7.3. SQLite views can't reference qualified table\n-- names (memory.foo) and still work when the database is opened standalone (DB\n-- Browser, sqlite CLI). Inline WHERE clauses in skills instead.\n\nCREATE TABLE IF NOT EXISTS memory.embeddings (\n  id              INTEGER PRIMARY KEY AUTOINCREMENT,\n  memory_id       INTEGER NOT NULL,\n  model           TEXT    NOT NULL,\n  dims            INTEGER NOT NULL,\n  vector          BLOB    NOT NULL,\n  embedded_field  TEXT    NOT NULL DEFAULT 'situation',\n  created_at      TEXT    NOT NULL DEFAULT (datetime('now')),\n  UNIQUE (memory_id, model, embedded_field),\n  FOREIGN KEY (memory_id) REFERENCES memories(id)\n);\n\nCREATE INDEX IF NOT EXISTS memory.idx_embeddings_memory ON embeddings(memory_id);\nCREATE INDEX IF NOT EXISTS memory.idx_embeddings_model  ON embeddings(model);\n\nCREATE TABLE IF NOT EXISTS memory.memory_links (\n  id              INTEGER PRIMARY KEY AUTOINCREMENT,\n  from_memory_id  INTEGER NOT NULL,\n  to_memory_id    INTEGER NOT NULL,\n  kind            TEXT    NOT NULL,\n  rationale       TEXT,\n  weight          REAL    NOT NULL DEFAULT 1.0,\n  created_at      TEXT    NOT NULL DEFAULT (datetime('now')),\n  created_by      TEXT    NOT NULL,\n  CHECK (kind IN ('contradicts', 'extends', 'derived_from', 'related', 'corrects')),\n  CHECK (from_memory_id != to_memory_id),\n  CHECK (weight >= 0.0 AND weight <= 1.0),\n  UNIQUE (from_memory_id, to_memory_id, kind),\n  FOREIGN KEY (from_memory_id) REFERENCES memories(id),\n  FOREIGN KEY (to_memory_id)   REFERENCES memories(id)\n);\n\nCREATE INDEX IF NOT EXISTS memory.idx_links_from ON memory_links(from_memory_id);\nCREATE INDEX IF NOT EXISTS memory.idx_links_to   ON memory_links(to_memory_id);\nCREATE INDEX IF NOT EXISTS memory.idx_links_kind ON memory_links(kind);\n\nCREATE TABLE IF NOT EXISTS memory.anatomy_snapshots (\n  id              INTEGER PRIMARY KEY AUTOINCREMENT,\n  taken_at        TEXT    NOT NULL DEFAULT (datetime('now')),\n  payload_json    TEXT    NOT NULL,\n  sha256          TEXT    NOT NULL UNIQUE,\n  taken_by        TEXT    NOT NULL,\n  git_sha         TEXT\n);\n\n-- Retrieval-feedback loop (the self-learning closure).\n-- Records: which memory was retrieved/used, in what context, with what score.\n-- Outcomes are SEPARATE rows in memory_use_outcomes (append-only; many\n-- ratings per use allowed — agent self-rates immediately, human re-rates\n-- later).\nCREATE TABLE IF NOT EXISTS memory.memory_uses (\n  id                INTEGER PRIMARY KEY AUTOINCREMENT,\n  memory_id         INTEGER NOT NULL,\n  used_at           TEXT    NOT NULL DEFAULT (datetime('now')),\n  used_by           TEXT    NOT NULL,\n  context_card      TEXT,\n  context_session   TEXT,\n  context_skill     TEXT,\n  retrieval_method  TEXT,\n  retrieval_score   REAL,\n  notes             TEXT,\n  CHECK (retrieval_method IN ('similarity', 'graph', 'rag-context', 'direct') OR retrieval_method IS NULL),\n  FOREIGN KEY (memory_id) REFERENCES memories(id)\n);\n\nCREATE INDEX IF NOT EXISTS memory.idx_memory_uses_memory ON memory_uses(memory_id);\nCREATE INDEX IF NOT EXISTS memory.idx_memory_uses_card   ON memory_uses(context_card);\nCREATE INDEX IF NOT EXISTS memory.idx_memory_uses_used_by ON memory_uses(used_by);\n\nCREATE TABLE IF NOT EXISTS memory.memory_use_outcomes (\n  id           INTEGER PRIMARY KEY AUTOINCREMENT,\n  use_id       INTEGER NOT NULL,\n  outcome      TEXT    NOT NULL,\n  rated_by     TEXT    NOT NULL,\n  rated_at     TEXT    NOT NULL DEFAULT (datetime('now')),\n  notes        TEXT,\n  CHECK (outcome IN ('helpful', 'irrelevant', 'misleading', 'partial')),\n  FOREIGN KEY (use_id) REFERENCES memory_uses(id)\n);\n\nCREATE INDEX IF NOT EXISTS memory.idx_use_outcomes_use     ON memory_use_outcomes(use_id);\nCREATE INDEX IF NOT EXISTS memory.idx_use_outcomes_outcome ON memory_use_outcomes(outcome);\n\n-- skills: materialized projection of .antiloki/skills/**/*.mjs reality.\n-- Populated on openDb by walking the disk + parsing AST. sha256 tracks drift —\n-- if a skill's file changes without re-seeding, queries return the stale\n-- description until anatomy-rescan refreshes. Catalog is queryable instead of\n-- having to load anatomy_snapshots JSON every time.\n-- memory.skills: registry of atomic capabilities (one row per .mjs file in\n-- .antiloki/skills/). Was: memory.subskills. The atomic capability layer.\n-- (Distinct from state.actions which is the wrapper/intent layer.)\nCREATE TABLE IF NOT EXISTS memory.skills (\n  id            INTEGER PRIMARY KEY AUTOINCREMENT,\n  name          TEXT    NOT NULL UNIQUE,\n  path          TEXT    NOT NULL,\n  description   TEXT,\n  input_schema  TEXT,\n  sha256        TEXT    NOT NULL,\n  lines         INTEGER NOT NULL,\n  first_seen_at TEXT    NOT NULL DEFAULT (datetime('now')),\n  last_seen_at  TEXT    NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE INDEX IF NOT EXISTS memory.idx_skills_sha ON skills(sha256);\n\n-- catalog_embeddings: vectors for system catalog entries (skills, actions,\n-- agents) — distinct from memory.embeddings (which is for user memories with\n-- FK to memories.id). No FK here because catalog names are TEXT identifiers,\n-- not row IDs. UNIQUE prevents duplicate vectors per (entity, model).\nCREATE TABLE IF NOT EXISTS memory.catalog_embeddings (\n  id             INTEGER PRIMARY KEY AUTOINCREMENT,\n  entity_type    TEXT    NOT NULL,\n  entity_name    TEXT    NOT NULL,\n  model          TEXT    NOT NULL,\n  dims           INTEGER NOT NULL,\n  vector         BLOB    NOT NULL,\n  embedded_text  TEXT    NOT NULL,\n  created_at     TEXT    NOT NULL DEFAULT (datetime('now')),\n  UNIQUE (entity_type, entity_name, model),\n  CHECK (entity_type IN ('action', 'action', 'agent', 'law', 'prompt', 'extract', 'memory-correction', 'card', 'contract'))\n);\n\nCREATE INDEX IF NOT EXISTS memory.idx_catalog_emb_lookup ON catalog_embeddings(entity_type, entity_name);\nCREATE INDEX IF NOT EXISTS memory.idx_catalog_emb_model  ON catalog_embeddings(model);\n\n-- Cross-DB graph-RAG (docs/graph-rag-cross-db.md): ONE vector index over every workspace DB EXCEPT\n-- state. rag_chunks = a projected + embedded text chunk from any source DB/table/row; rag_edges = the\n-- graph over them (kNN cosine neighbours + explicit cross-DB id references). Powers cross-DB\n-- deepsearch + the Knowledge graph canvas. content_hash makes the embedding sweep incremental.\nCREATE TABLE IF NOT EXISTS memory.rag_chunks (\n  id           INTEGER PRIMARY KEY AUTOINCREMENT,\n  source_db    TEXT    NOT NULL,           -- 'brain'|'laws'|'knowledge'|'timeline'|'code'|'judgments'|'memory'\n  source_table TEXT    NOT NULL,\n  source_row   TEXT    NOT NULL,           -- the row's PK as TEXT (any key shape)\n  chunk_ix     INTEGER NOT NULL DEFAULT 0, -- a row may split into N chunks\n  text         TEXT    NOT NULL,\n  content_hash TEXT    NOT NULL,           -- sha256(text) → skip re-embed when unchanged\n  vector       BLOB    NOT NULL,           -- Float32Array bytes\n  model        TEXT    NOT NULL,           -- e.g. 'ollama:nomic-embed-text'\n  dim          INTEGER NOT NULL,\n  updated_at   TEXT    NOT NULL DEFAULT (datetime('now')),\n  UNIQUE (source_db, source_table, source_row, chunk_ix)\n);\nCREATE INDEX IF NOT EXISTS memory.idx_rag_src ON rag_chunks(source_db, source_table);\n\nCREATE TABLE IF NOT EXISTS memory.rag_edges (\n  from_chunk INTEGER NOT NULL,\n  to_chunk   INTEGER NOT NULL,\n  kind       TEXT    NOT NULL,             -- 'knn' (cosine neighbour) | 'ref' (cross-DB id mention)\n  score      REAL    NOT NULL,             -- cosine for knn, 1.0 for ref\n  PRIMARY KEY (from_chunk, to_chunk, kind)\n);\nCREATE INDEX IF NOT EXISTS memory.idx_rag_edge_to ON rag_edges(to_chunk);\n\n-- FEAT-BRAIN-CONSOLIDATE-BEFORE-PRUNE (migration 126, user directive\n-- 2026-06-10): durable digest of a window of AI interactions, written\n-- BEFORE the corresponding brain.ai_calls.envelope_json rows may be\n-- pruned. The envelopes are the raw transcript; this is the consolidated\n-- context (overview / analysis / keypoints / learnings / fails / journey)\n-- that survives pruning and is usable as RAG context or sliced cache.\n-- NOT an audited entity (derived digest, like anatomy_snapshots).\nCREATE TABLE IF NOT EXISTS memory.memory_consolidation (\n  id               INTEGER PRIMARY KEY AUTOINCREMENT,\n  created_at       TEXT    NOT NULL DEFAULT (datetime('now')),\n  source           TEXT    NOT NULL DEFAULT 'ai_calls',\n  period_start     TEXT    NOT NULL,\n  period_end       TEXT    NOT NULL,\n  calls_count      INTEGER NOT NULL,\n  cost_usd_total   REAL,\n  tokens_in_total  INTEGER,\n  tokens_out_total INTEGER,\n  overview_md      TEXT    NOT NULL,\n  analysis_md      TEXT,\n  keypoints_json   TEXT,   -- structured [{kind, text, weight}] for slicing\n  learnings_md     TEXT,\n  fails_md         TEXT,\n  journey_md       TEXT,\n  meta_json        TEXT,\n  pruned_at        TEXT    -- set when the covered envelopes were NULLed\n);\nCREATE INDEX IF NOT EXISTS memory.idx_memory_consolidation_period\n  ON memory_consolidation(period_end);\n""#).expect("MEMORY_SCHEMA: embedded JSON is valid by construction")
});

pub static BRAIN_SCHEMA: LazyLock<Value> = LazyLock::new(|| {
    serde_json::from_str(r#""\n-- Brain layer: driver runtime state + reasoning + concurrency.\n-- All tables live in attached 'brain' database (brain.sqlite).\n-- Brain mutations do NOT go through with-audit — these tables ARE the audit\n-- log for the brain's own operations. Auditing the audit would be circular.\n-- No views (DB Browser-safe per the lesson from v0.7.3).\n\n-- brain_fires: every agent invocation. Two-phase: INSERT on start (ended_at\n-- NULL), UPDATE on completion to fill duration/tokens/cost/outcome. The row\n-- is write-once-per-field; we just defer some fields.\nCREATE TABLE IF NOT EXISTS brain.brain_fires (\n  id              INTEGER PRIMARY KEY AUTOINCREMENT,\n  session_id      TEXT    NOT NULL,\n  fired_at        TEXT    NOT NULL DEFAULT (datetime('now')),\n  ended_at        TEXT,\n  card_slug       TEXT,\n  agent           TEXT    NOT NULL,\n  action           TEXT    NOT NULL,\n  inferred_state  TEXT,\n  duration_ms     INTEGER,\n  tokens_in       INTEGER,\n  tokens_out      INTEGER,\n  cost_usd        REAL,\n  outcome         TEXT,\n  result_summary  TEXT,\n  CHECK (outcome IN ('success','failed','timeout','rejected','truncated') OR outcome IS NULL)\n);\n\nCREATE INDEX IF NOT EXISTS brain.idx_brain_fires_session ON brain_fires(session_id);\nCREATE INDEX IF NOT EXISTS brain.idx_brain_fires_card    ON brain_fires(card_slug);\nCREATE INDEX IF NOT EXISTS brain.idx_brain_fires_agent   ON brain_fires(agent);\n\n-- brain_decisions: every reasoning step the driver takes. Append-only.\n-- Session lifecycle lives here too (decision='session_start' / 'session_end').\n-- inputs_json captures everything the driver looked at — key to determinism.\nCREATE TABLE IF NOT EXISTS brain.brain_decisions (\n  id              INTEGER PRIMARY KEY AUTOINCREMENT,\n  session_id      TEXT    NOT NULL,\n  decided_at      TEXT    NOT NULL DEFAULT (datetime('now')),\n  card_slug       TEXT,\n  decision        TEXT    NOT NULL,\n  rationale       TEXT    NOT NULL,\n  inputs_json     TEXT,\n  fire_id         INTEGER,\n  CHECK (decision IN ('fire','wait','rollback','escalate','done','pause','session_start','session_end','goal_set',\n    -- FEAT-AGENT-REASONING-LOG: broader reasoning kinds beyond driver loop.\n    -- Agents log judgment calls (classify, gate verdicts, rule matches, etc.)\n    -- so \"why did X decide Y?\" is queryable in brain.brain_decisions.\n    'classify','gate_verdict','rule_match','sandbox_create','review_pass','schedule_and_dispatch','agent_step'))\n);\n\nCREATE INDEX IF NOT EXISTS brain.idx_brain_decisions_session ON brain_decisions(session_id);\nCREATE INDEX IF NOT EXISTS brain.idx_brain_decisions_card    ON brain_decisions(card_slug);\nCREATE INDEX IF NOT EXISTS brain.idx_brain_decisions_type    ON brain_decisions(decision);\n\n-- brain_locks: current concurrency state. The only mutable-as-state table\n-- in brain.sqlite. INSERT to acquire, DELETE to release. PK enforces no\n-- double-acquire on the same resource.\nCREATE TABLE IF NOT EXISTS brain.brain_locks (\n  resource_type     TEXT NOT NULL,\n  resource_id       TEXT NOT NULL,\n  state             TEXT NOT NULL,\n  holder_session    TEXT NOT NULL,\n  acquired_at       TEXT NOT NULL DEFAULT (datetime('now')),\n  expires_at        TEXT,\n  reason            TEXT,\n  PRIMARY KEY (resource_type, resource_id),\n  CHECK (resource_type IN ('card', 'agent')),\n  CHECK (state IN ('driving','thinking','executing','waiting'))\n);\n\nCREATE INDEX IF NOT EXISTS brain.idx_brain_locks_holder ON brain_locks(holder_session);\n\n-- driver_ticks: one row per iteration of the orchestration loop. Append-only.\n-- A tick INSERTs with outcome='running' on entry, then UPDATEs with the\n-- terminal outcome on exit. card_slug+decided_action are NULL when the\n-- tick was idle (no actionable card). fired_event_id links forward into\n-- sacred_timeline so each tick is traceable to its audit row.\n-- Filed under FEAT-DRIVER-ORCHESTRATION (step 1).\nCREATE TABLE IF NOT EXISTS brain.driver_ticks (\n  id              INTEGER PRIMARY KEY AUTOINCREMENT,\n  started_at      TEXT    NOT NULL DEFAULT (datetime('now')),\n  card_slug       TEXT,\n  decided_agent   TEXT,\n  decided_action  TEXT,\n  decided_reason  TEXT,\n  fired_event_id  INTEGER,\n  outcome         TEXT    NOT NULL DEFAULT 'running',\n  cost_usd        REAL    DEFAULT 0,\n  duration_ms     INTEGER,\n  ended_at        TEXT,\n  error_message   TEXT,\n  facts_json      TEXT,            -- FEAT-DRIVER-DIAGNOSIS: the state-machine decision INPUTS snapshot\n                                   -- (every fact the matched rule saw) — the \"why\" a postmortem needs.\n  CHECK (outcome IN ('running','fired','idle','blocked','failed','escalated','budget_capped','halt_requested'))\n);\n\nCREATE INDEX IF NOT EXISTS brain.idx_driver_ticks_card    ON driver_ticks(card_slug);\nCREATE INDEX IF NOT EXISTS brain.idx_driver_ticks_outcome ON driver_ticks(outcome);\nCREATE INDEX IF NOT EXISTS brain.idx_driver_ticks_started ON driver_ticks(started_at);\n\n-- FEAT-DRIVER-DIAGNOSIS (migration 166): one DEDUPED diagnosis per failure SIGNATURE. The gather\n-- (a driver-inspect snapshot) is deterministic (P1); classification + root cause + fix are MAN's AI\n-- interpretation (P2, nullable until then). recurrences counts how often the signature has fired —\n-- the \"learn from patterns\" axis. A brand-new table → CREATE IF NOT EXISTS lands it everywhere.\nCREATE TABLE IF NOT EXISTS brain.driver_diagnoses (\n  id               INTEGER PRIMARY KEY AUTOINCREMENT,\n  signature        TEXT NOT NULL UNIQUE,           -- (decided_action :: error_class) — the dedup key\n  tick_id          INTEGER,                        -- the latest tick that hit this signature\n  card_slug        TEXT,\n  classification   TEXT,                           -- P2: 'card-bug'|'substrate-gap'|'config'|'transient'\n  root_cause_md    TEXT,                            -- P2\n  suggested_fix_md TEXT,                            -- P2\n  confidence       REAL,                            -- P2\n  gather_json      TEXT,                            -- the driver-inspect snapshot (latest occurrence)\n  recurrences      INTEGER NOT NULL DEFAULT 1,\n  model_id         TEXT,\n  created_at       TEXT NOT NULL DEFAULT (datetime('now')),\n  updated_at       TEXT NOT NULL DEFAULT (datetime('now'))\n);\nCREATE INDEX IF NOT EXISTS brain.idx_driver_diagnoses_card ON driver_diagnoses(card_slug);\n\n-- brain_prompts table removed 2026-05-21 (migration 032). Conversation\n-- history now lives in state.interviewer_turns. The brain_prompts schema was\n-- a parallel design that never got wired up.\n\n-- bench_runs: performance measurements over time. Each row = one (metric,\n-- value) sample. run_id ties metrics from one bench invocation together.\n-- git_sha correlates regressions to commits.\nCREATE TABLE IF NOT EXISTS brain.bench_runs (\n  id            INTEGER PRIMARY KEY AUTOINCREMENT,\n  ts            TEXT    NOT NULL DEFAULT (datetime('now')),\n  run_id        TEXT    NOT NULL,\n  bench_name    TEXT    NOT NULL,\n  metric        TEXT    NOT NULL,\n  value         REAL    NOT NULL,\n  unit          TEXT,\n  context_json  TEXT,\n  git_sha       TEXT\n);\n\nCREATE INDEX IF NOT EXISTS brain.idx_bench_runs_run    ON bench_runs(run_id, bench_name);\nCREATE INDEX IF NOT EXISTS brain.idx_bench_runs_bench  ON bench_runs(bench_name, metric, ts);\nCREATE INDEX IF NOT EXISTS brain.idx_bench_runs_sha    ON bench_runs(git_sha);\n\n-- eval_runs: SWE-bench-style eval harness results. One row = one task run in one sweep.\n-- solved=1 iff the held-out oracle (validate_cmd) went fail->pass with no regress — the\n-- grade is external to the system's own QA. failure_class is the taxonomy when unsolved.\n-- See docs/eval-harness.md.\nCREATE TABLE IF NOT EXISTS brain.eval_runs (\n  id             INTEGER PRIMARY KEY AUTOINCREMENT,\n  ts             TEXT    NOT NULL DEFAULT (datetime('now')),\n  sweep_id       TEXT    NOT NULL,\n  task_id        TEXT    NOT NULL,\n  card_slug      TEXT,\n  solved         INTEGER NOT NULL DEFAULT 0,\n  oracle_before  INTEGER,\n  oracle_after   INTEGER,\n  halted_reason  TEXT,\n  failure_class  TEXT,\n  ticks          INTEGER,\n  ai_cost_usd    REAL    DEFAULT 0,\n  wall_seconds   REAL,\n  provider_mode  TEXT,\n  git_sha        TEXT,\n  notes_md       TEXT\n);\n\nCREATE INDEX IF NOT EXISTS brain.idx_eval_runs_sweep ON eval_runs(sweep_id, task_id);\nCREATE INDEX IF NOT EXISTS brain.idx_eval_runs_task  ON eval_runs(task_id, ts);\n\n-- ── AI infrastructure (provider-agnostic) ────────────────────────────\n-- Naming convention (AI-NAMING-CONVENTION law):\n--   tier        ∈ {low, mid, high}                — capability\n--   temperature ∈ {freezed, cold, warm, hot, hell} — 0.0/0.2/0.5/0.8/1.0+\n-- Provider mapping happens in brain.ai_providers (swap providers via SQL).\n\nCREATE TABLE IF NOT EXISTS brain.ai_providers (\n  id        INTEGER PRIMARY KEY AUTOINCREMENT,\n  -- 'image' = the generation tier (2026-07-20): image-OUTPUT models, exclusive\n  -- bucket, resolved by ai-image-call — never part of the text rotation.\n  tier      TEXT    NOT NULL CHECK (tier IN ('low','mid','high','image')),\n  provider  TEXT    NOT NULL,\n  model_id  TEXT    NOT NULL,\n  active    INTEGER NOT NULL DEFAULT 1,\n  -- PROVIDER-FAILOVER: per-tier failover order. 0 = primary, 1 = first\n  -- fallback, 2 = second fallback. ai-call tries active rows in this order\n  -- and falls through to the next on an IO_ERROR (e.g. an empty/errored\n  -- OpenRouter response). One active row per (tier, failover_rank).\n  failover_rank INTEGER NOT NULL DEFAULT 0,\n  cost_per_1m_input_tokens_usd  REAL,\n  cost_per_1m_output_tokens_usd REAL,\n  max_context_tokens INTEGER,\n  notes_md  TEXT,\n  -- FEAT-PROVIDER-ADAPTER-INTERFACE: relative path (from project root)\n  -- to the adapter module implementing the ProviderAdapter contract\n  -- defined in .antiloki/skills/external/provider-adapter.contract.mjs.\n  -- NULL means use ai-call's fallback if-chain (legacy behavior).\n  adapter_module TEXT,\n  created_at TEXT NOT NULL DEFAULT (datetime('now')),\n  UNIQUE (tier, provider, model_id)\n);\nCREATE INDEX IF NOT EXISTS brain.idx_ai_providers_active ON ai_providers(tier) WHERE active = 1;\n\n-- Routing defaults: deterministic task_kind → tier/temperature lookup.\n-- AI-ROUTER-V2-ADAPTIVE will optionally RAG over ai_calls history later.\nCREATE TABLE IF NOT EXISTS brain.routing_defaults (\n  id            INTEGER PRIMARY KEY AUTOINCREMENT,\n  task_kind     TEXT    NOT NULL UNIQUE,\n  tier          TEXT    NOT NULL CHECK (tier IN ('low','mid','high')),\n  temperature   TEXT    NOT NULL CHECK (temperature IN ('freezed','cold','warm','hot','hell')),\n  max_tokens    INTEGER NOT NULL DEFAULT 1024,\n  rationale_md  TEXT,\n  created_at    TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\n-- ── HEIMDALL H0 — identity & taxonomy (docs/heimdall-plan.md §4, §5.1) ──\n-- The problem taxonomy the casting router speaks: families → categories (a tree, so\n-- sparse evidence can roll up), 4 shared weight profiles, and the deterministic\n-- template→category mapping keyed by BASE name (minus the trailing .vN — a version\n-- bump must not orphan its category). Evidence/ledger/castings tables land in H1.\nCREATE TABLE IF NOT EXISTS brain.heimdall_weight_profiles (\n  slug          TEXT PRIMARY KEY,\n  title         TEXT NOT NULL,\n  weights_json  TEXT NOT NULL,\n  created_at    TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS brain.heimdall_categories (\n  slug            TEXT PRIMARY KEY,\n  family          TEXT NOT NULL CHECK (family IN ('BUILD','DESIGN','JUDGMENT','LANGUAGE','REASONING')),\n  title           TEXT NOT NULL,\n  description_md  TEXT NOT NULL DEFAULT '',\n  weight_profile  TEXT NOT NULL,\n  status          TEXT NOT NULL DEFAULT 'dormant' CHECK (status IN ('active','dormant')),\n  graded_by       TEXT NOT NULL DEFAULT 'both' CHECK (graded_by IN ('deterministic','rubric','both')),\n  created_at      TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS brain.heimdall_template_categories (\n  template_base  TEXT PRIMARY KEY,\n  category       TEXT NOT NULL,\n  created_at     TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\n-- ── HEIMDALL H1 — evidence & observability (plan §5.1, §5.7-bis) ──\n-- castings: one row per real dispatch, trace_json = the FULL decision walk (classify,\n-- gate floor, ladder rungs with sample counts, filters, score table with evidence\n-- aggregates, decision+reason). H1 records reason='observe' (old router decided);\n-- H2 flips the decision, never the format. Append-only telemetry (brain class).\nCREATE TABLE IF NOT EXISTS brain.heimdall_castings (\n  id              INTEGER PRIMARY KEY AUTOINCREMENT,\n  ai_call_id      INTEGER,\n  template_base   TEXT,\n  category        TEXT NOT NULL,\n  requested_tier  TEXT NOT NULL,\n  effective_model TEXT,\n  reason          TEXT NOT NULL CHECK (reason IN ('observe','override','ledger','probe','quarantine','passthrough','floor_raise')),\n  trace_json      TEXT NOT NULL,\n  ts              TEXT NOT NULL DEFAULT (datetime('now'))\n);\nCREATE INDEX IF NOT EXISTS brain.idx_heimdall_castings_call ON heimdall_castings(ai_call_id);\nCREATE INDEX IF NOT EXISTS brain.idx_heimdall_castings_cat  ON heimdall_castings(category, ts);\n\n-- evidence: append-only; the ledger is ALWAYS re-derivable from this + ai_calls\n-- (heimdall-validate recomputes and diffs). provenance decides trust (plan §5.2).\nCREATE TABLE IF NOT EXISTS brain.heimdall_evidence (\n  id             INTEGER PRIMARY KEY AUTOINCREMENT,\n  model_slug     TEXT NOT NULL,\n  category       TEXT NOT NULL,\n  template_base  TEXT,\n  provenance     TEXT NOT NULL CHECK (provenance IN ('prod_gate','prod_court','prod_terminal','bench_det','bench_rubric','playground','human','ai_judge','ai_panel','lineage_prior')),\n  outcome        TEXT NOT NULL CHECK (outcome IN ('clean','fail','burn','ship')),\n  ai_call_id     INTEGER,\n  bench_item_id  INTEGER,\n  human_tag_id   INTEGER,\n  ai_tag_id      INTEGER,\n  ts             TEXT NOT NULL DEFAULT (datetime('now'))\n);\nCREATE INDEX IF NOT EXISTS brain.idx_heimdall_evidence_scope ON heimdall_evidence(category, model_slug, ts);\n-- attribute() idempotency: one evidence row per (call, provenance, outcome).\nCREATE UNIQUE INDEX IF NOT EXISTS brain.uq_heimdall_evidence_call ON heimdall_evidence(ai_call_id, provenance, outcome) WHERE ai_call_id IS NOT NULL;\n\n-- ledger: materialized rates per (model × ladder rung × window). Rebuilt whole by\n-- heimdall-ledger-rebuild (derivability invariant — never incrementally patched).\n-- P-1 (prompt dimension, plan §0 #14): 'template_version' = the finest rung — per FULL\n-- template name (chat.v11 vs chat.v18), measurement-only until P-3 casting.\nCREATE TABLE IF NOT EXISTS brain.heimdall_ledger (\n  model_slug     TEXT NOT NULL,\n  scope_kind     TEXT NOT NULL CHECK (scope_kind IN ('template_version','template','category','family','global')),\n  scope_ref      TEXT NOT NULL,\n  window_days    INTEGER NOT NULL,\n  calls          INTEGER NOT NULL DEFAULT 0,\n  clean          INTEGER NOT NULL DEFAULT 0,\n  fails          INTEGER NOT NULL DEFAULT 0,\n  burns          INTEGER NOT NULL DEFAULT 0,\n  ships          INTEGER NOT NULL DEFAULT 0,\n  weighted_score REAL,\n  sample_ok      INTEGER NOT NULL DEFAULT 0,\n  computed_at    TEXT NOT NULL DEFAULT (datetime('now')),\n  PRIMARY KEY (model_slug, scope_kind, scope_ref, window_days)\n);\n\n-- per-GATE daily AI spend ceilings (operator 2026-07-04): a gate whose calls have spent\n-- >= ceiling_usd TODAY refuses further dispatch (same shape as the tier daily caps, scoped\n-- to one template base). Absent row = no ceiling. Edited inline on Settings → Heimdall → Gates.\nCREATE TABLE IF NOT EXISTS brain.heimdall_gate_ceilings (\n  template_base  TEXT PRIMARY KEY,\n  ceiling_usd    REAL NOT NULL CHECK (ceiling_usd > 0),\n  updated_at     TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\n-- TRAINING-tab skips (operator 2026-07-04): \"skip\" in the rapid-tagging queue is\n-- persistent — a skipped call never reappears (a skip is \"I can't judge this one\",\n-- not evidence; it carries no trust and touches no ledger).\nCREATE TABLE IF NOT EXISTS brain.heimdall_tag_skips (\n  ai_call_id  INTEGER PRIMARY KEY,\n  ts          TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\n-- PROMPT tags (operator 2026-07-05): a DISTINCT tagging dimension — the subject is the\n-- PROMPT VERSION (full template name), not the model's output. \"Was this prompt well\n-- designed?\" vs the model tags' \"did the model do well?\". Scores live in their OWN scale\n-- (never heimdall_evidence / the model ledger); human latest-wins per version, AI\n-- latest-wins per (version × exemplar call). Feeds the P-2/P-3 prompt arc.\nCREATE TABLE IF NOT EXISTS brain.heimdall_prompt_tags (\n  id                  INTEGER PRIMARY KEY AUTOINCREMENT,\n  template_name       TEXT NOT NULL,\n  verdict             INTEGER NOT NULL CHECK (verdict IN (-2,-1,1,2)),\n  confidence          REAL,\n  reason_md           TEXT,\n  failure_class       TEXT,   -- prompt taxonomy: ambiguous|missing-context|contradictory|overlong|wrong-constraints|format-trap|other\n  source              TEXT NOT NULL CHECK (source IN ('human','ai')),\n  exemplar_ai_call_id INTEGER,\n  judge_ai_call_id    INTEGER,\n  ts                  TEXT NOT NULL DEFAULT (datetime('now'))\n);\nCREATE INDEX IF NOT EXISTS brain.idx_heimdall_prompt_tags_name ON heimdall_prompt_tags(template_name);\n\n-- AI tags (plan: heimdall-ai-tagging.md): a high-tier judge's verdict on an answer — the\n-- FALLBACK evidence tier (trust below human + court). One row per judged call; judge_ai_call_id\n-- links to the tagger's OWN ai-call (enveloped + viewable in the AI window). A human tag on the\n-- same call supersedes this for the ledger (human > AI), but the record persists for accuracy.\nCREATE TABLE IF NOT EXISTS brain.heimdall_ai_tags (\n  id                INTEGER PRIMARY KEY AUTOINCREMENT,\n  target_ai_call_id INTEGER NOT NULL,\n  verdict           INTEGER NOT NULL CHECK (verdict IN (-2,-1,1,2)),\n  confidence        REAL,\n  reason_md         TEXT,\n  -- AI-4: structured failure taxonomy for negative verdicts\n  -- (wrong-name | hallucinated-dep | incomplete | style | off-scope | degenerate | other)\n  failure_class     TEXT,\n  -- AI-1: below the confidence gate — the tag is recorded but writes NO evidence, and the\n  -- call is routed to the TOP of the human queue (\"the AI asked for a human\").\n  low_confidence    INTEGER NOT NULL DEFAULT 0,\n  -- AI-2: panel mode — per-seat verdicts/confidences/judge calls; agree = all seats one sign.\n  panel_json        TEXT,\n  panel_agree       INTEGER,\n  judge_ai_call_id  INTEGER,\n  judge_model       TEXT,\n  superseded_by_human INTEGER NOT NULL DEFAULT 0,\n  ts                TEXT NOT NULL DEFAULT (datetime('now')),\n  UNIQUE (target_ai_call_id)\n);\n\n-- AI-3 (human-committed half): per-(provenance × category) trust overrides. The calibration\n-- report RECOMMENDS a value when the AI judge disagrees with humans in a category; the\n-- operator COMMITS it here (system.heimdall.trust.set). category NULL = provenance-global.\n-- ledger-rebuild resolves: (provenance,category) → (provenance,NULL) → PROVENANCE_TRUST.\nCREATE TABLE IF NOT EXISTS brain.heimdall_trust_overrides (\n  provenance  TEXT NOT NULL,\n  category    TEXT NOT NULL DEFAULT '',   -- '' = provenance-global (NULL would break the PK upsert)\n  trust       REAL NOT NULL CHECK (trust >= 0 AND trust <= 1),\n  reason_md   TEXT,\n  updated_at  TEXT NOT NULL DEFAULT (datetime('now')),\n  PRIMARY KEY (provenance, category)\n);\n\n-- human tags (plan §0 #13): the operator's verdict on an answer — the strongest\n-- evidence tier. verdict has NO zero (a neutral tag is noise). Reason text also lands\n-- as a correction memory via the tagging action (H2 surfaces).\nCREATE TABLE IF NOT EXISTS brain.heimdall_human_tags (\n  id           INTEGER PRIMARY KEY AUTOINCREMENT,\n  verdict      INTEGER NOT NULL CHECK (verdict IN (-2,-1,1,2)),\n  reason_md    TEXT,\n  surface      TEXT NOT NULL CHECK (surface IN ('chat','card','pr','playground','castings')),\n  ai_call_id   INTEGER,\n  card_slug    TEXT,\n  message_ref  TEXT,\n  tagged_by    TEXT NOT NULL DEFAULT 'operator',\n  ts           TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\n-- ── AI call infrastructure (AI-CALL-INFRA card #65) ──────────────────\n-- Normalized: every prompt output field is a ROW, never a JSON blob.\n\n-- Prompt templates: versioned. Name = stable identifier; version bumps\n-- on body or output-shape changes. Active row per name is the one with\n-- superseded_by IS NULL.\nCREATE TABLE IF NOT EXISTS brain.prompt_templates (\n  id                     INTEGER PRIMARY KEY AUTOINCREMENT,\n  name                   TEXT    NOT NULL,\n  version                INTEGER NOT NULL,\n  template_md            TEXT    NOT NULL,\n  default_tier           TEXT    NOT NULL CHECK (default_tier IN ('low','mid','high')),\n  default_temperature    TEXT    NOT NULL CHECK (default_temperature IN ('freezed','cold','warm','hot','hell')),\n  max_output_tokens      INTEGER NOT NULL DEFAULT 1024,\n  superseded_by          INTEGER REFERENCES prompt_templates(id),\n  created_at             TEXT    NOT NULL DEFAULT (datetime('now')),\n  -- FEAT-CROSS-FIELD-CONSISTENCY-LINT (migration 077):\n  -- JSON array of {id, expression, message} rules evaluated by ai-call\n  -- after structural lint passes. Rules see the parsed output + context.\n  cross_field_rules_json TEXT,\n  -- judging_criteria (operator 2026-07-05): 3-5 decidable statements of what a GOOD output\n  -- looks like for this gate, declared once at registration. Utility/meta gates have\n  -- CONSTANT success criteria (no per-call acceptance) — taggers and the AI judge read\n  -- them from here. JSON array of strings.\n  judging_criteria_json TEXT,\n  -- WS-2 prompt-quality program (migration 128): optional system-role\n  -- message sent as a leading {role:'system'} by provider adapters.\n  system_md              TEXT,\n  -- WS-3 (migration 128): 'single' or 'reason_then_format' — ai-call runs\n  -- the companion '<name>.reason' template first and feeds its output\n  -- into this template's {{reasoning_output}} placeholder.\n  phase_flow             TEXT    NOT NULL DEFAULT 'single',\n  UNIQUE (name, version)\n);\nCREATE INDEX IF NOT EXISTS brain.idx_prompt_templates_active\n  ON prompt_templates(name) WHERE superseded_by IS NULL;\n\n-- Output shape: one row per field a prompt is expected to return.\nCREATE TABLE IF NOT EXISTS brain.prompt_output_fields (\n  id                     INTEGER PRIMARY KEY AUTOINCREMENT,\n  prompt_template_id     INTEGER NOT NULL REFERENCES prompt_templates(id),\n  field_name             TEXT    NOT NULL,\n  field_type             TEXT    NOT NULL\n    CHECK (field_type IN ('string','number','boolean','enum','array_of_string','array_of_object')),\n  enum_values            TEXT,    -- pipe-separated; reused for string-enum via structural lint\n  required               INTEGER NOT NULL DEFAULT 1,\n  description            TEXT,\n  order_index            INTEGER NOT NULL,\n  -- EPIC-PROMPTS-AS-FILLED-TEMPLATES-STRUCTURAL-LINT (migration 076)\n  min_length             INTEGER,\n  max_length             INTEGER,\n  required_sections_json TEXT,    -- JSON array of section header strings\n  pattern                TEXT,    -- regex source (no /.../ wrapper)\n  -- FEAT-GROUNDED-REFERENCES (migration 078):\n  -- JSON array of entity-type tags to verify in this field's value.\n  -- Recognized: card_slug, contract_slug, file_path.\n  grounded_refs_json     TEXT,\n  UNIQUE (prompt_template_id, field_name)\n);\n\n-- Input shape: one row per structured input a prompt EXPECTS to be fed\n-- (the twin of prompt_output_fields). The model is still fed rendered\n-- markdown; this table locks the STRUCTURE of input_kv before render so\n-- every invocation of a template carries the same shape of facts.\n-- ai-call validates input_kv against these rows (WARN by default, strict\n-- via ANTILOKI_STRICT_INPUT_CHECK). No rows for a template = no-op.\nCREATE TABLE IF NOT EXISTS brain.prompt_input_fields (\n  id                     INTEGER PRIMARY KEY AUTOINCREMENT,\n  prompt_template_id     INTEGER NOT NULL REFERENCES prompt_templates(id),\n  field_name             TEXT    NOT NULL,\n  field_type             TEXT    NOT NULL\n    CHECK (field_type IN ('string','number','boolean','enum','array_of_string','array_of_object')),\n  enum_values            TEXT,    -- pipe-separated; reused for string-enum via structural lint\n  required               INTEGER NOT NULL DEFAULT 1,\n  description            TEXT,\n  order_index            INTEGER NOT NULL,\n  min_length             INTEGER,\n  max_length             INTEGER,\n  required_sections_json TEXT,    -- JSON array of section header strings\n  pattern                TEXT,    -- regex source (no /.../ wrapper)\n  UNIQUE (prompt_template_id, field_name)\n);\n\n-- Every AI invocation. cache key = (template_id, input_hash, tier, temp).\nCREATE TABLE IF NOT EXISTS brain.ai_calls (\n  id                    INTEGER PRIMARY KEY AUTOINCREMENT,\n  ts                    TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),\n  prompt_template_id    INTEGER NOT NULL REFERENCES prompt_templates(id),\n  tier                  TEXT    NOT NULL CHECK (tier IN ('low','mid','high')),\n  temperature           TEXT    NOT NULL CHECK (temperature IN ('freezed','cold','warm','hot','hell')),\n  provider              TEXT,\n  model_id              TEXT,\n  input_hash            TEXT    NOT NULL,\n  duration_ms           REAL,\n  cost_usd_actual       REAL,\n  tokens_in             INTEGER,\n  tokens_out            INTEGER,\n  -- FEAT-CACHE-TELEMETRY (migration 130): input tokens the PROVIDER served\n  -- from its prompt cache (DeepSeek/Qwen automatic prefix caching). Distinct\n  -- from the 'cached' column below (the substrate's exact-identity cache).\n  tokens_cached         INTEGER NOT NULL DEFAULT 0,\n  cached                INTEGER NOT NULL DEFAULT 0,\n  cache_source_call_id  INTEGER REFERENCES ai_calls(id),\n  parent_event_id       INTEGER,  -- runtime_events.id (cross-DB; no FK enforcement)\n  outcome               TEXT    NOT NULL\n    CHECK (outcome IN ('success','error','timeout','validation_failed')),\n  -- OUTCOME CLASS (2026-09-19): the graded verdict ai-outcome-report writes after the call — clean ·\n  -- degenerate · truncated · … — read by Heimdall's prompt tags, the model scoreboard, the failure feed.\n  -- Was queried everywhere but never declared (a JS-era backfill); open-db adds it to older DBs.\n  outcome_class         TEXT,\n  -- FEAT-AI-CALL-REPLAY (migration 055): when this row was produced by\n  -- ai-call-replay, points back at the original ai_calls.id. NULL on\n  -- normal/cached/failed-original calls.\n  replay_of_id          INTEGER REFERENCES ai_calls(id),\n  -- EPIC-INTERACTION-ENVELOPE (migration 105): the canonical interaction\n  -- envelope (inputs + references + attachments) assembled per call by\n  -- assemble-context-envelope. NULL on rows written before this existed.\n  envelope_json         TEXT,\n  -- EPIC-AI-BEHAVIOR-STUDY (migration 134): the format leg of a two-phase\n  -- call (reason_then_format / AUTO_TWO_PHASE) points at its reason twin.\n  -- NULL on single-phase calls and pre-migration rows.\n  reason_call_id        INTEGER REFERENCES ai_calls(id),\n  -- FEAT-OPENROUTER-SESSION-TRACKING (migration 137): the per-card-run\n  -- OpenRouter session this call rode under (cards.openrouter_session_id\n  -- at dispatch time). NULL for calls outside a driver run.\n  session_id            TEXT,\n  -- FEAT-OPENROUTER-LOG-RETRIEVAL (migration 139): OpenRouter's generation id\n  -- for this fresh call, so its prompt+completion text can be fetched from\n  -- OpenRouter (GET /api/v1/generation/content?id=). NULL for cache hits,\n  -- non-OpenRouter providers, and pre-migration rows.\n  openrouter_generation_id TEXT,\n  -- EPIC-SUBAGENT (migration 145): the sub-agent LEAF this call ran as (tl.dev.style,\n  -- qa.lawyer, …). NULL for non-swarm calls + pre-migration rows. Powers per-leaf\n  -- attribution in the waterfall + per-leaf cost/telemetry.\n  subagent              TEXT,\n  -- EPIC-DRIVER-WATERFALL-REDESIGN (migration 147): the contract this call was\n  -- made for. Structural card/contract attribution so card-process-events\n  -- surfaces swarm leaf calls (whose input_kv never contains the card slug)\n  -- without the fragile value_text LIKE '%slug%' substring match. NULL for\n  -- calls not scoped to a contract. The per-call PERSONA is intentionally NOT\n  -- stored (bloat); the inspector re-resolves it from subagent at detail-time.\n  contract_slug         TEXT,\n  -- FEAT-PROCESS-TERMINAL-TAB: the reasoning chain a LOCAL reasoning model\n  -- (Ollama deepseek-r1) emitted as <think>…</think>. The adapter captures it\n  -- (instead of silently dropping it) so the Terminal tab can show the thinking.\n  -- NULL for non-reasoning models + OpenRouter (which returns reasoning separately).\n  reasoning_md          TEXT\n);\nCREATE INDEX IF NOT EXISTS brain.idx_ai_calls_cache\n  ON ai_calls(prompt_template_id, input_hash, tier, temperature)\n  WHERE outcome = 'success' AND cached = 0;\nCREATE INDEX IF NOT EXISTS brain.idx_ai_calls_ts ON ai_calls(ts);\n-- FIX-TIMELINE-JOIN-FULL-SCAN (migration 132): the audit-timeline /\n-- cost-attribution joins probe ai_calls by parent_event_id; without this\n-- partial index each probe full-scanned the table (envelope blobs included).\nCREATE INDEX IF NOT EXISTS brain.idx_ai_calls_parent_event\n  ON ai_calls(parent_event_id) WHERE parent_event_id IS NOT NULL;\n-- NOTE: idx_ai_calls_reason (on reason_call_id) lives ONLY in migration 134.\n-- The fold cannot carry it: on a pre-134 DB the column doesn't exist yet\n-- (CREATE TABLE IF NOT EXISTS skips, but CREATE INDEX still resolves columns\n-- and would crash openDb before the migration runner ever gets a chance).\n\n-- Output fields per ai_call (one row per field; arrays become multiple rows\n-- with same field_name, distinct order_index).\nCREATE TABLE IF NOT EXISTS brain.ai_call_outputs (\n  id                INTEGER PRIMARY KEY AUTOINCREMENT,\n  ai_call_id        INTEGER NOT NULL REFERENCES ai_calls(id),\n  field_name        TEXT    NOT NULL,\n  value_text        TEXT,\n  value_number      REAL,\n  value_boolean     INTEGER,\n  order_index       INTEGER NOT NULL DEFAULT 0,\n  parent_output_id  INTEGER REFERENCES ai_call_outputs(id)\n);\nCREATE INDEX IF NOT EXISTS brain.idx_ai_call_outputs_call ON ai_call_outputs(ai_call_id);\n\n-- FEAT-AI-CALL-INPUTS-PERSISTED (migration 053): the input_kv set the\n-- substrate sent to the AI on every non-cached call. Cache hits inherit\n-- via the existing ai_calls.cache_source_call_id link — no duplication.\nCREATE TABLE IF NOT EXISTS brain.ai_call_inputs (\n  id          INTEGER PRIMARY KEY AUTOINCREMENT,\n  ai_call_id  INTEGER NOT NULL REFERENCES ai_calls(id),\n  key         TEXT    NOT NULL,\n  value_text  TEXT,\n  order_index INTEGER NOT NULL DEFAULT 0\n);\nCREATE INDEX IF NOT EXISTS brain.idx_ai_call_inputs_call ON ai_call_inputs(ai_call_id);\n\n-- FEAT-AI-CALL-RENDERED-PROMPT-PERSISTED (migration 054): the\n-- post-{{placeholder}}-substitution prompt the AI literally received,\n-- plus provider request metadata. Opt-in via env ANTILOKI_AUDIT_RENDERED_PROMPTS=1.\nCREATE TABLE IF NOT EXISTS brain.ai_call_rendered (\n  ai_call_id          INTEGER PRIMARY KEY REFERENCES ai_calls(id),\n  rendered_prompt_md  TEXT NOT NULL,\n  system_message      TEXT,\n  request_meta_json   TEXT\n);\n\n-- EPIC-CONTEXT-BUNDLE (migration 173): the bone+sliced context bundle assembled for a call\n-- (docs/context-bundle.md §6). One row per ai_call — the STRUCTURED provenance behind\n-- ai_call_inputs' flat code_context value: per-item tier/type/source/tokens/relevance/freshness\n-- (+ text, for expand), plus what was dropped (over budget) and skipped (producer deferred/empty).\n-- The FE glass-box Context tab reads this; also answers \"what context did call X actually get?\".\nCREATE TABLE IF NOT EXISTS brain.context_bundles (\n  ai_call_id    INTEGER PRIMARY KEY REFERENCES ai_calls(id),\n  agent         TEXT,\n  phase         TEXT,\n  bone_tokens   INTEGER NOT NULL DEFAULT 0,\n  sliced_tokens INTEGER NOT NULL DEFAULT 0,\n  total_tokens  INTEGER NOT NULL DEFAULT 0,\n  budget        INTEGER,\n  over_budget   INTEGER NOT NULL DEFAULT 0,\n  items_json    TEXT,\n  dropped_json  TEXT,\n  skipped_json  TEXT,\n  created_at    TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\n-- EPIC-AI-BEHAVIOR-STUDY (migration 134): per-attempt audit trail of the\n-- ai-call retry ladder — the retry correction banner, the raw output of\n-- EACH attempt, and the structured validation errors (previously thrown,\n-- never persisted). Rows exist only when validation failed at least once.\nCREATE TABLE IF NOT EXISTS brain.ai_call_attempts (\n  id                     INTEGER PRIMARY KEY AUTOINCREMENT,\n  ai_call_id             INTEGER NOT NULL REFERENCES ai_calls(id),\n  attempt_no             INTEGER NOT NULL,\n  ts                     TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),\n  outcome                TEXT    NOT NULL CHECK (outcome IN ('success','validation_failed','error')),\n  correction_md          TEXT,             -- retry banner PREPENDED for THIS attempt (NULL on attempt 1)\n  raw_output_md          TEXT,             -- the model's raw answer on THIS attempt (100KB cap)\n  validation_errors_json TEXT,             -- structured lint errors (NULL when ok)\n  UNIQUE (ai_call_id, attempt_no)\n);\nCREATE INDEX IF NOT EXISTS brain.idx_ai_call_attempts_call ON ai_call_attempts(ai_call_id);\n\n-- EPIC-AI-BEHAVIOR-STUDY (migration 135): postmortem diagnoses of AI\n-- failures, written by ai-call-postmortem. failure_class enum mirrors\n-- FAILURE_CLASSES in skills/ai/failure-classes.mjs (canary-tested —\n-- edit BOTH or the canary breaks). narrative_md is the LLM leg, filled\n-- only from the prompt-quality aggregator context.\nCREATE TABLE IF NOT EXISTS brain.ai_call_reports (\n  id                    INTEGER PRIMARY KEY AUTOINCREMENT,\n  ts                    TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')),\n  ai_call_id            INTEGER REFERENCES ai_calls(id),   -- nullable: stage failures may lack a call\n  prompt_template_id    INTEGER REFERENCES prompt_templates(id),\n  prompt_name           TEXT,\n  prompt_version        INTEGER,\n  tier                  TEXT,\n  model_id              TEXT,\n  related_action        TEXT,\n  related_contract_slug TEXT,\n  related_card_slug     TEXT,\n  trigger               TEXT NOT NULL CHECK (trigger IN\n                          ('ai_call_validation','stage_lint','driver_tick','manual')),\n  failure_class         TEXT NOT NULL CHECK (failure_class IN\n                          ('vague_spec','dropped_reason_decisions','invented_structure',\n                           'format_noncompliance','byte_drift','truncation','refusal_empty',\n                           'feed_gap','provider_error','validation_other')),\n  severity              TEXT NOT NULL DEFAULT 'warn' CHECK (severity IN ('info','warn','error')),\n  evidence_json         TEXT NOT NULL,\n  diagnosis_md          TEXT NOT NULL,\n  narrative_md          TEXT,\n  recommendation_md     TEXT,\n  retry_recovered       INTEGER NOT NULL DEFAULT 0,\n  created_by            TEXT NOT NULL DEFAULT 'ai-call-postmortem'\n);\nCREATE INDEX IF NOT EXISTS brain.idx_aicr_call     ON ai_call_reports(ai_call_id);\nCREATE INDEX IF NOT EXISTS brain.idx_aicr_prompt   ON ai_call_reports(prompt_name, prompt_version);\nCREATE INDEX IF NOT EXISTS brain.idx_aicr_class_ts ON ai_call_reports(failure_class, ts);\nCREATE INDEX IF NOT EXISTS brain.idx_aicr_contract ON ai_call_reports(related_contract_slug);\n\n-- FEAT-CODE-IMPORT-GRAPH: static import edges between workspace files.\n-- to_path is the resolved workspace-relative target (NULL for bare/package\n-- specifiers). Cache rebuilt by code-imports; scoped by workspace_id.\nCREATE TABLE IF NOT EXISTS brain.code_connections (\n  id           INTEGER PRIMARY KEY AUTOINCREMENT,\n  workspace_id INTEGER NOT NULL,\n  from_path    TEXT    NOT NULL,\n  specifier    TEXT    NOT NULL,\n  to_path      TEXT,\n  created_at   TEXT    NOT NULL DEFAULT (datetime('now')),\n  UNIQUE (workspace_id, from_path, specifier)\n);\nCREATE INDEX IF NOT EXISTS brain.idx_code_conn_to ON code_connections (workspace_id, to_path);\n\nCREATE TABLE IF NOT EXISTS brain.code_file_metadata (\n  id               INTEGER PRIMARY KEY AUTOINCREMENT,\n  workspace_id     INTEGER NOT NULL,\n  path             TEXT    NOT NULL,\n  sha256           TEXT    NOT NULL,\n  summary          TEXT,\n  score            INTEGER,\n  suggestions_json TEXT,\n  ai_call_id       INTEGER,\n  created_at       TEXT    NOT NULL DEFAULT (datetime('now')),\n  UNIQUE (workspace_id, path, sha256)\n);\n""#).expect("BRAIN_SCHEMA: embedded JSON is valid by construction")
});

pub static LAWS_SCHEMA: LazyLock<Value> = LazyLock::new(|| {
    serde_json::from_str(r#""\n-- Laws layer: invariants the system MUST/MUST NOT do. Replaces the\n-- advisory CLAUDE.md/protocol.md approach with deterministic enforcement.\n-- AI can't \"forget\" a law — it's queried, checked, and (for hard laws)\n-- blocked at the runtime layer that the AI couldn't bypass even if it\n-- tried. Less cognition, more deterministic.\n--\n-- Cross-DB linkage is by TEXT slug convention (source_card → cards.slug,\n-- source_event → sacred_timeline.id, source_memory → memory.memories.id).\n-- No views (DB Browser-safe per v0.7.3 lesson).\n--\n-- Append-only via superseded_by: laws don't get DELETEd, they get replaced.\n-- This preserves the audit trail of WHEN a law changed and WHY.\n\nCREATE TABLE IF NOT EXISTS laws.laws (\n  id                INTEGER PRIMARY KEY AUTOINCREMENT,\n  slug              TEXT    NOT NULL UNIQUE,\n  kind              TEXT    NOT NULL,\n  domain            TEXT    NOT NULL,\n  title             TEXT    NOT NULL,\n  statement         TEXT    NOT NULL,\n  rationale         TEXT    NOT NULL,\n  enforcement       TEXT    NOT NULL,\n  enforcement_hook  TEXT,\n  trigger_sql       TEXT,\n  established_at    TEXT    NOT NULL DEFAULT (datetime('now')),\n  established_by    TEXT    NOT NULL,\n  source_card       TEXT,\n  source_event      INTEGER,\n  source_memory     INTEGER,\n  superseded_by     INTEGER,\n  superseded_at     TEXT,\n  CHECK (kind IN ('constitutional', 'procedural', 'permission', 'constraint', 'decision', 'principle')),\n  CHECK (enforcement IN ('hard', 'soft', 'archived')),\n  FOREIGN KEY (superseded_by) REFERENCES laws(id)\n);\n\nCREATE INDEX IF NOT EXISTS laws.idx_laws_active\n  ON laws(kind, domain) WHERE superseded_by IS NULL;\nCREATE INDEX IF NOT EXISTS laws.idx_laws_enforce\n  ON laws(enforcement, enforcement_hook) WHERE superseded_by IS NULL AND enforcement_hook IS NOT NULL;\nCREATE INDEX IF NOT EXISTS laws.idx_laws_slug ON laws(slug);\n\n-- Each law can have sub-statements: exceptions, conditions, examples,\n-- antipatterns, consequences. Normalized so they're queryable per-law.\nCREATE TABLE IF NOT EXISTS laws.law_clauses (\n  id            INTEGER PRIMARY KEY AUTOINCREMENT,\n  law_id        INTEGER NOT NULL,\n  clause_type   TEXT    NOT NULL,\n  text          TEXT    NOT NULL,\n  order_index   INTEGER NOT NULL DEFAULT 0,\n  created_at    TEXT    NOT NULL DEFAULT (datetime('now')),\n  CHECK (clause_type IN ('exception', 'condition', 'example', 'antipattern', 'consequence')),\n  FOREIGN KEY (law_id) REFERENCES laws(id)\n);\n\nCREATE INDEX IF NOT EXISTS laws.idx_law_clauses_law ON law_clauses(law_id, order_index);\n\n-- Laws relate to each other: NEVER_BYPASS_AUDIT refines NEVER_FALSIFY_PROTOCOL_STATE.\n-- Knowing the graph helps AI: \"if I check law X, also check its refiners.\"\nCREATE TABLE IF NOT EXISTS laws.law_links (\n  id             INTEGER PRIMARY KEY AUTOINCREMENT,\n  from_law_id    INTEGER NOT NULL,\n  to_law_id      INTEGER NOT NULL,\n  kind           TEXT    NOT NULL,\n  rationale      TEXT,\n  created_at     TEXT    NOT NULL DEFAULT (datetime('now')),\n  CHECK (kind IN ('refines', 'extends', 'supersedes', 'contradicts', 'enforces', 'specializes')),\n  CHECK (from_law_id != to_law_id),\n  UNIQUE (from_law_id, to_law_id, kind),\n  FOREIGN KEY (from_law_id) REFERENCES laws(id),\n  FOREIGN KEY (to_law_id)   REFERENCES laws(id)\n);\n\n-- Every attempted breach gets logged — blocked, warned, escaped, or\n-- allowed-exception. Reveals patterns over time + catches enforcement\n-- failures (escaped=1 means a hard law's hook returned valid when it\n-- shouldn't have; needs post-mortem).\nCREATE TABLE IF NOT EXISTS laws.law_violations (\n  id              INTEGER PRIMARY KEY AUTOINCREMENT,\n  law_id          INTEGER NOT NULL,\n  attempted_at    TEXT    NOT NULL DEFAULT (datetime('now')),\n  attempted_by    TEXT    NOT NULL,\n  agent_name      TEXT,\n  action_name      TEXT,\n  context_json    TEXT,\n  outcome         TEXT    NOT NULL,\n  CHECK (outcome IN ('blocked', 'warned', 'escaped', 'allowed_exception')),\n  FOREIGN KEY (law_id) REFERENCES laws(id)\n);\n\nCREATE INDEX IF NOT EXISTS laws.idx_violations_law      ON law_violations(law_id);\nCREATE INDEX IF NOT EXISTS laws.idx_violations_agent    ON law_violations(agent_name, attempted_at);\nCREATE INDEX IF NOT EXISTS laws.idx_violations_outcome  ON law_violations(outcome, attempted_at);\n\n-- Card scoring rubric (facet × level 1-5 → definition): authoritative DATA fed\n-- to card-score so the risk/complexity/priority rules are editable without a\n-- code change. Originally added by migration 20260529-108; created here too so\n-- a fresh workspace (which does NOT replay migrations) gets the table.\n-- seedScoringRubric() seeds the rows idempotently on every openDb.\nCREATE TABLE IF NOT EXISTS laws.scoring_rubric (\n  id             INTEGER PRIMARY KEY AUTOINCREMENT,\n  facet          TEXT    NOT NULL,\n  level          INTEGER NOT NULL,\n  definition     TEXT    NOT NULL,\n  established_at TEXT    NOT NULL DEFAULT (datetime('now')),\n  established_by TEXT    NOT NULL DEFAULT 'migration:20260529-108',\n  UNIQUE (facet, level),\n  CHECK (level BETWEEN 1 AND 5),\n  CHECK (facet IN ('risk', 'complexity', 'priority'))\n);\n\n-- FEAT-ENV-FLAGS-REGISTRY (operator 2026-07-11): every ANTILOKI_* env flag is\n-- a ROW — docs/env-flags.md is RENDERED from here, the BE boot log reads\n-- danger tiers from here, and the census canary asserts every process.env\n-- read in the code has a row (LESS_COGNITION_MORE_DETERMINISTIC: the system\n-- carries the flag inventory, not anyone's memory). Values stay in env by\n-- design (bootstrap paths, env-as-trust-boundary, emergency rollbacks).\n-- Mirrored by migration 20260711-174 for existing DBs; seedEnvFlags() keeps\n-- rows current on every openDb.\nCREATE TABLE IF NOT EXISTS laws.env_flags (\n  name          TEXT PRIMARY KEY,\n  category      TEXT NOT NULL,\n  danger_tier   TEXT NOT NULL CHECK (danger_tier IN ('safe', 'caution', 'enforcement-defeating')),\n  reads_at      TEXT NOT NULL CHECK (reads_at IN ('boot', 'per-call', 'test-only')),\n  default_value TEXT,\n  description   TEXT NOT NULL,\n  added_at      TEXT NOT NULL DEFAULT (datetime('now'))\n);\n""#).expect("LAWS_SCHEMA: embedded JSON is valid by construction")
});

pub static KNOWLEDGE_SCHEMA: LazyLock<Value> = LazyLock::new(|| {
    serde_json::from_str(r#""\n-- SKILL LIBRARY (operator 2026-07-25): teachable AGENT skills — real skills, not prompt injection.\n-- Each row is a skill: an index line (description = when to use), the full method (body_md), and\n-- executable ASSETS (files materialized into a pane's worktree as .claude/skills/<slug>/ — Claude Code\n-- loads them natively; other engines get an AGENTS.md index). Lives in knowledge (learned craft).\nCREATE TABLE IF NOT EXISTS knowledge.skill_library (\n  id           INTEGER PRIMARY KEY AUTOINCREMENT,\n  slug         TEXT    NOT NULL UNIQUE,\n  name         TEXT    NOT NULL,\n  description  TEXT    NOT NULL,             -- the WHEN-TO-USE index line (progressive disclosure)\n  body_md      TEXT    NOT NULL DEFAULT '',\n  assets_json  TEXT    NOT NULL DEFAULT '{}', -- { \"relative/path\": \"content\" } — real files, runnable\n  applies_json TEXT    NOT NULL DEFAULT '{}', -- { engines?: [], globs?: [] }\n  verify_cmd   TEXT,                          -- optional proof-of-use command\n  enabled      INTEGER NOT NULL DEFAULT 1,\n  version      INTEGER NOT NULL DEFAULT 1,\n  provenance   TEXT    NOT NULL DEFAULT 'authored', -- authored | minted | imported | promoted\n  created_at   TEXT    NOT NULL DEFAULT (datetime('now')),\n  updated_at   TEXT    NOT NULL DEFAULT (datetime('now'))\n);\n\n-- Knowledge layer: curated index of external source material from\n-- .antiloki/knowledge/ vault. AI never reads vault files directly —\n-- only this curated extract index. Vault = library; knowledge.sqlite =\n-- librarian's card catalog.\n--\n-- documents table tracks each source file (PDF, MD, image, external URL)\n-- with sha256 for change detection. extracts table holds the curated\n-- insights (quotes, figures, code blocks, summaries) with provenance\n-- back to source + page/section. Embeddings reuse memory.catalog_embeddings\n-- with entity_type='extract' for semantic search.\n\nCREATE TABLE IF NOT EXISTS knowledge.documents (\n  id              INTEGER PRIMARY KEY AUTOINCREMENT,\n  vault_path      TEXT    NOT NULL UNIQUE,\n  doc_type        TEXT    NOT NULL,\n  sha256          TEXT    NOT NULL,\n  bytes           INTEGER NOT NULL,\n  summary         TEXT,\n  ingested_at     TEXT    NOT NULL DEFAULT (datetime('now')),\n  ingested_by     TEXT    NOT NULL,\n  external_source TEXT,\n  superseded_by   INTEGER,\n  superseded_at   TEXT,\n  CHECK (doc_type IN ('md', 'pdf', 'image', 'code', 'external', 'note')),\n  FOREIGN KEY (superseded_by) REFERENCES documents(id)\n);\n\nCREATE INDEX IF NOT EXISTS knowledge.idx_documents_active\n  ON documents(doc_type, vault_path) WHERE superseded_by IS NULL;\nCREATE INDEX IF NOT EXISTS knowledge.idx_documents_sha ON documents(sha256);\n\nCREATE TABLE IF NOT EXISTS knowledge.extracts (\n  id              INTEGER PRIMARY KEY AUTOINCREMENT,\n  document_id     INTEGER NOT NULL,\n  extract_type    TEXT    NOT NULL,\n  text            TEXT    NOT NULL,\n  context         TEXT,\n  page_or_section TEXT,\n  created_at      TEXT    NOT NULL DEFAULT (datetime('now')),\n  created_by      TEXT    NOT NULL,\n  CHECK (extract_type IN ('quote', 'figure', 'insight', 'code', 'diagram', 'summary', 'note')),\n  FOREIGN KEY (document_id) REFERENCES documents(id)\n);\n\nCREATE INDEX IF NOT EXISTS knowledge.idx_extracts_document ON extracts(document_id);\nCREATE INDEX IF NOT EXISTS knowledge.idx_extracts_type     ON extracts(extract_type);\n\nCREATE TABLE IF NOT EXISTS knowledge.document_links (\n  id              INTEGER PRIMARY KEY AUTOINCREMENT,\n  from_doc_id     INTEGER NOT NULL,\n  to_doc_id       INTEGER NOT NULL,\n  kind            TEXT    NOT NULL,\n  rationale       TEXT,\n  created_at      TEXT    NOT NULL DEFAULT (datetime('now')),\n  CHECK (kind IN ('cites', 'extends', 'contradicts', 'related', 'supersedes')),\n  CHECK (from_doc_id != to_doc_id),\n  UNIQUE (from_doc_id, to_doc_id, kind),\n  FOREIGN KEY (from_doc_id) REFERENCES documents(id),\n  FOREIGN KEY (to_doc_id)   REFERENCES documents(id)\n);\n\n-- BOOK IMPORTATION (operator 2026-07-26): a technical book, decomposed DETERMINISTICALLY into\n-- ordered blocks BEFORE any AI, then imported wave by wave — each wave one scoped call that rides\n-- the previous chapters' SNAPSHOTS as rolling context. Cost is governed (budget → cost_break,\n-- pause/resume). AI output lands as STAGING rows (concepts / law drafts / skill drafts) — never\n-- auto-ratified; the operator harvests them into laws.sqlite / skill_library explicitly.\nCREATE TABLE IF NOT EXISTS knowledge.books (\n  id           INTEGER PRIMARY KEY AUTOINCREMENT,\n  title        TEXT    NOT NULL,\n  author       TEXT,\n  goal         TEXT    NOT NULL DEFAULT '',   -- WHY this book is being imported (rides every wave)\n  synopsis_md  TEXT    NOT NULL DEFAULT '',   -- rolling synopsis (seeded by the first wave)\n  source_kind  TEXT    NOT NULL DEFAULT 'text',\n  tokens_est   INTEGER NOT NULL DEFAULT 0,\n  blocks       INTEGER NOT NULL DEFAULT 0,\n  tier         TEXT    NOT NULL DEFAULT 'shelf',  -- shelf | reference | canon (integration gate)\n  created_at   TEXT    NOT NULL DEFAULT (datetime('now'))\n);\nCREATE TABLE IF NOT EXISTS knowledge.book_blocks (\n  id         INTEGER PRIMARY KEY AUTOINCREMENT,\n  book_id    INTEGER NOT NULL,\n  ord        INTEGER NOT NULL,\n  title      TEXT    NOT NULL,\n  text       TEXT    NOT NULL,\n  tokens_est INTEGER NOT NULL DEFAULT 0,\n  FOREIGN KEY (book_id) REFERENCES books(id)\n);\nCREATE INDEX IF NOT EXISTS knowledge.idx_book_blocks ON book_blocks(book_id, ord);\nCREATE TABLE IF NOT EXISTS knowledge.book_runs (\n  id          INTEGER PRIMARY KEY AUTOINCREMENT,\n  book_id     INTEGER NOT NULL,\n  status      TEXT    NOT NULL DEFAULT 'running',  -- running | paused | cost_break | done | error\n  budget_usd  REAL,                                -- the cost break — reaching it pauses the mission\n  spent_usd   REAL    NOT NULL DEFAULT 0,\n  cursor      INTEGER NOT NULL DEFAULT 0,          -- next block ord to import\n  error       TEXT,\n  created_at  TEXT    NOT NULL DEFAULT (datetime('now')),\n  updated_at  TEXT    NOT NULL DEFAULT (datetime('now')),\n  FOREIGN KEY (book_id) REFERENCES books(id)\n);\nCREATE TABLE IF NOT EXISTS knowledge.book_snapshots (\n  id           INTEGER PRIMARY KEY AUTOINCREMENT,\n  book_id      INTEGER NOT NULL,\n  block_ord    INTEGER NOT NULL,\n  snapshot_md  TEXT    NOT NULL,\n  quality_json TEXT    NOT NULL DEFAULT '{}',\n  ai_call_id   INTEGER,\n  cost_usd     REAL,\n  created_at   TEXT    NOT NULL DEFAULT (datetime('now')),\n  UNIQUE (book_id, block_ord),\n  FOREIGN KEY (book_id) REFERENCES books(id)\n);\nCREATE TABLE IF NOT EXISTS knowledge.book_concepts (\n  id         INTEGER PRIMARY KEY AUTOINCREMENT,\n  book_id    INTEGER NOT NULL,\n  block_ord  INTEGER NOT NULL,\n  term       TEXT    NOT NULL,\n  definition TEXT    NOT NULL,\n  ref        TEXT,\n  FOREIGN KEY (book_id) REFERENCES books(id)\n);\nCREATE TABLE IF NOT EXISTS knowledge.book_law_drafts (\n  id          INTEGER PRIMARY KEY AUTOINCREMENT,\n  book_id     INTEGER NOT NULL,\n  block_ord   INTEGER NOT NULL,\n  key         TEXT    NOT NULL,\n  statement   TEXT    NOT NULL,\n  why         TEXT    NOT NULL DEFAULT '',\n  example     TEXT    NOT NULL DEFAULT '',\n  antipattern TEXT    NOT NULL DEFAULT '',\n  ref         TEXT,\n  status      TEXT    NOT NULL DEFAULT 'draft',   -- draft | harvested | dismissed\n  FOREIGN KEY (book_id) REFERENCES books(id)\n);\n-- THE PAPER CORPUS (operator 2026-07-26): every pressed paper registers itself so papers can cite\n-- one another — prior editions get their projections graded against today's measurement, and\n-- \"Related work\" becomes literature, not links. Idempotent by cite_id; deterministic; no AI.\nCREATE TABLE IF NOT EXISTS knowledge.papers (\n  id            INTEGER PRIMARY KEY AUTOINCREMENT,\n  cite_id       TEXT    NOT NULL UNIQUE,\n  kind          TEXT    NOT NULL DEFAULT 'folder',\n  subject       TEXT    NOT NULL,\n  snapshot_id   INTEGER,\n  title         TEXT    NOT NULL,\n  findings_json TEXT    NOT NULL DEFAULT '{}',\n  created_at    TEXT    NOT NULL DEFAULT (datetime('now'))\n);\nCREATE INDEX IF NOT EXISTS knowledge.idx_papers_subject ON papers(subject, id);\n\n-- NARRATION IR (2026-07-27, operator greenlight) — \"intelligence stops at the IR\". The compiler\n-- writes a lossless, append-only-versioned narration (nir-1: say/pause/breath/event units, every\n-- say carries its source receipt). Renderers are pinned executors; a render row is the FIDELITY\n-- RECEIPT (features requested vs honored — \"build our own renderer\" is a QUERY on degraded_json,\n-- never intuition). Audio bytes live on disk; the DB keeps hashes.\nCREATE TABLE IF NOT EXISTS knowledge.narrations (\n  id           INTEGER PRIMARY KEY AUTOINCREMENT,\n  source_kind  TEXT    NOT NULL,               -- paper | book_module | text\n  source_key   TEXT    NOT NULL,               -- cite_id | book-<id>-m<ord> | caller-chosen\n  title        TEXT    NOT NULL,\n  ir_version   TEXT    NOT NULL DEFAULT 'nir-1',\n  ir_json      TEXT    NOT NULL,               -- the lossless IR — same file feeds every backend forever\n  ir_hash      TEXT    NOT NULL,\n  units_count  INTEGER NOT NULL,\n  words        INTEGER NOT NULL DEFAULT 0,\n  duration_est_ms INTEGER NOT NULL DEFAULT 0,  -- printed assumption: 155 wpm + event durations\n  created_at   TEXT    NOT NULL DEFAULT (datetime('now')),\n  UNIQUE (source_kind, source_key, ir_hash)\n);\nCREATE TABLE IF NOT EXISTS knowledge.narration_renders (\n  id            INTEGER PRIMARY KEY AUTOINCREMENT,\n  narration_id  INTEGER NOT NULL,\n  section_ord   INTEGER,                       -- NULL = the whole narration; else one section's press\n  section_title TEXT,\n  backend       TEXT    NOT NULL,              -- kokoro | espeak | elevenlabs | …\n  backend_version TEXT,\n  voice         TEXT,\n  waveform_path TEXT,\n  waveform_hash TEXT,\n  duration_ms   INTEGER,\n  features_requested_json TEXT NOT NULL DEFAULT '[]',\n  features_honored_json   TEXT NOT NULL DEFAULT '[]',\n  degraded_json           TEXT NOT NULL DEFAULT '[]',\n  timing_json   TEXT,                          -- per-unit say timings {i,role,t,d} — Video Cast sync\n  cost_usd      REAL    NOT NULL DEFAULT 0,\n  created_at    TEXT    NOT NULL DEFAULT (datetime('now')),\n  FOREIGN KEY (narration_id) REFERENCES narrations(id)\n);\n\n-- PRESS PROGRESS (2026-08-12): press telemetry that OUTLIVES the thread doing the pressing.\n-- It used to be a process-local Mutex<HashMap> inside the addon, so only the thread running the\n-- press could ever read it. That was invisible while the press ran inline on the main thread; the\n-- moment it moves to a worker, op:'progress' on the request path reads a DIFFERENT map, finds\n-- nothing, and the progress bar sits at zero forever. A row is readable by any connection (WAL\n-- gives concurrent readers alongside the writing worker), which is what makes a detached press\n-- observable at all. progress_key is the PK, so re-pressing the same section REPLACES the row and\n-- a stale job can never be mistaken for the live one.\nCREATE TABLE IF NOT EXISTS knowledge.narration_press_progress (\n  progress_key  TEXT    PRIMARY KEY,           -- '<narration_id>:<section_ord>' | '<narration_id>:all'\n  narration_id  INTEGER NOT NULL,\n  section_ord   INTEGER,                       -- NULL = the whole narration, matching narration_renders\n  status        TEXT    NOT NULL DEFAULT 'pressing',  -- pressing | done | error\n  done          INTEGER NOT NULL DEFAULT 0,    -- units synthesised so far\n  total         INTEGER NOT NULL DEFAULT 0,    -- units in this slice\n  render_id     INTEGER,                       -- set when the press lands its receipt row\n  error         TEXT,                          -- truncated failure text; presence ends the poll\n  started_at    REAL    NOT NULL,              -- ms epoch — the 30min staleness check reads this\n  updated_at    REAL    NOT NULL,\n  FOREIGN KEY (narration_id) REFERENCES narrations(id)\n);\n\n-- REASONING IR (rir-1, 2026-07-27 operator greenlight: \"completely free, like the papers\") — a\n-- reasoning SESSION as typed, receipted moves (observe/question/hypothesize/evidence/object/\n-- concede/revise/unknown/callback/cite/conclude/confidence) walked from a mode grammar over a\n-- SEEDED bounded template library. $0 — no AI anywhere; same source + same seed ⇒ the same\n-- episode forever (the seed is IN the receipt). The podcast is renderer #1: the session projects\n-- to a nir narration (say units carry voice_role a|b) and the ENTIRE press stack reuses.\nCREATE TABLE IF NOT EXISTS knowledge.reasoning_sessions (\n  id           INTEGER PRIMARY KEY AUTOINCREMENT,\n  source_kind  TEXT    NOT NULL,               -- paper | text\n  source_key   TEXT    NOT NULL,               -- cite_id\n  title        TEXT    NOT NULL,\n  mode         TEXT    NOT NULL,               -- investigation | teaching (printed topology→grammar table)\n  reasoner     TEXT    NOT NULL DEFAULT 'curious', -- the Reasoner's OBJECTIVE: curious | skeptic\n  seed         INTEGER NOT NULL,               -- the 🎲 — printed, auditable, re-rollable\n  ir_version   TEXT    NOT NULL DEFAULT 'rir-1',\n  ir_json      TEXT    NOT NULL,               -- { moves:[{id,sp,type,text,claims,depends_on?,target?}], segments, voices }\n  ir_hash      TEXT    NOT NULL,\n  moves_count  INTEGER NOT NULL,\n  narration_id INTEGER,                        -- the nir projection this session pressed into\n  open_questions INTEGER NOT NULL DEFAULT 0,   -- filed into knowledge_units (kind question, consumer ultra-review)\n  created_at   TEXT    NOT NULL DEFAULT (datetime('now')),\n  UNIQUE (source_kind, source_key, ir_hash)\n);\n\n-- THE IR (P1.5, 2026-07-27) — the compiler's intermediate representation: verified, receipted,\n-- consumer-named knowledge units. Consumers read the IR, NEVER the staging tables. A row without\n-- a consumer is refused at the skill gate (knowledge-ir) — knowledge-hoarding is a bug.\nCREATE TABLE IF NOT EXISTS knowledge.knowledge_units (\n  id            INTEGER PRIMARY KEY AUTOINCREMENT,\n  kind          TEXT    NOT NULL,               -- fact|concept|heuristic|trade-off|doctrine|question|method|example|metric-link\n  identity_key  TEXT    NOT NULL,               -- normalized identity — consensus/versioning/dialogue are QUERIES on this\n  title         TEXT    NOT NULL,\n  body_json     TEXT    NOT NULL DEFAULT '{}',  -- the unit's typed payload (definition/statement/question/claims/…)\n  receipts_json TEXT    NOT NULL DEFAULT '[]',  -- [{block_ord,line,quote}] — every unit traces to its source\n  type_class    TEXT    NOT NULL DEFAULT 'definition', -- definition|normative|example|anecdote|opinion (ordinal honesty)\n  authority     TEXT    NOT NULL,               -- the source (book title first; RFCs/docs later)\n  edition       TEXT,\n  year          INTEGER,\n  applies_to    TEXT    NOT NULL DEFAULT '[]',  -- [languages/frameworks/domains] — the review engine filters by OUR stack\n  exceptions_json TEXT  NOT NULL DEFAULT '[]',  -- the authority's own qualifications, kept verbatim\n  consumers_json  TEXT  NOT NULL,               -- NON-EMPTY list — detector|question|ontology|glossary|rag|paper|metric-link|ultra-review|law-draft|skilllib\n  book_id       INTEGER,                        -- provenance link while books are the only authority\n  verdict       TEXT    NOT NULL DEFAULT 'kept',-- kept (warden-passed) | unverified (deterministic import)\n  created_at    TEXT    NOT NULL DEFAULT (datetime('now')),\n  UNIQUE (kind, identity_key, authority)\n);\nCREATE INDEX IF NOT EXISTS knowledge.idx_units_identity ON knowledge_units(identity_key, kind);\nCREATE INDEX IF NOT EXISTS knowledge.idx_units_book ON knowledge_units(book_id, kind);\nCREATE TABLE IF NOT EXISTS knowledge.unit_edges (\n  id         INTEGER PRIMARY KEY AUTOINCREMENT,\n  from_unit  INTEGER NOT NULL,\n  to_unit    INTEGER NOT NULL,\n  kind       TEXT    NOT NULL,                  -- IS_A|REQUIRES|RELATED|CONFLICTS|SUPPORTS|DESCENDS|REFINES\n  topic      TEXT,\n  receipts_json TEXT NOT NULL DEFAULT '[]',\n  created_at TEXT    NOT NULL DEFAULT (datetime('now')),\n  UNIQUE (from_unit, to_unit, kind),\n  FOREIGN KEY (from_unit) REFERENCES knowledge_units(id),\n  FOREIGN KEY (to_unit) REFERENCES knowledge_units(id)\n);\n-- THE BOOK MAP (2026-07-27): human corrections over the deterministic atlas. The atlas stays a\n-- pure recompute; annotations are the supervised layer merged on top — rejected detections drop,\n-- moved ones re-anchor, added ones join, payload overrides (term/zone/label) win. The swarm\n-- consumes the EFFECTIVE slots, so a correction changes what gets extracted.\nCREATE TABLE IF NOT EXISTS knowledge.book_annotations (\n  id         INTEGER PRIMARY KEY AUTOINCREMENT,\n  book_id    INTEGER NOT NULL,\n  tool       TEXT    NOT NULL,                 -- definitions|normatives|questions|tradeoffs|listings|procedures|glossary|summaries|callouts|figures|exercises|structure\n  slot_key   TEXT    NOT NULL,                 -- the detection's deterministic identity\n  status     TEXT    NOT NULL DEFAULT 'confirmed', -- confirmed | rejected | moved | added\n  block_ord  INTEGER,                          -- corrected anchor (moved/added)\n  line       INTEGER,\n  payload_json TEXT  NOT NULL DEFAULT '{}',    -- corrected fields (term/label/zone/quote)\n  note       TEXT,\n  created_at TEXT    NOT NULL DEFAULT (datetime('now')),\n  UNIQUE (book_id, tool, slot_key),\n  FOREIGN KEY (book_id) REFERENCES books(id)\n);\n-- the SWARM's run state (P2/P3): cursors over the atlas's deterministic slot lists.\nCREATE TABLE IF NOT EXISTS knowledge.book_swarm_runs (\n  id          INTEGER PRIMARY KEY AUTOINCREMENT,\n  book_id     INTEGER NOT NULL,\n  status      TEXT    NOT NULL DEFAULT 'running', -- running | paused | cost_break | done | error\n  budget_usd  REAL,\n  spent_usd   REAL    NOT NULL DEFAULT 0,\n  cursors_json TEXT   NOT NULL DEFAULT '{}',      -- per-slot-type progress index\n  skips_json  TEXT    NOT NULL DEFAULT '{}',      -- refused/killed counts per type (printed, honest)\n  error       TEXT,\n  created_at  TEXT    NOT NULL DEFAULT (datetime('now')),\n  updated_at  TEXT    NOT NULL DEFAULT (datetime('now')),\n  FOREIGN KEY (book_id) REFERENCES books(id)\n);\n\nCREATE TABLE IF NOT EXISTS knowledge.book_skill_drafts (\n  id          INTEGER PRIMARY KEY AUTOINCREMENT,\n  book_id     INTEGER NOT NULL,\n  block_ord   INTEGER NOT NULL,\n  name        TEXT    NOT NULL,\n  description TEXT    NOT NULL DEFAULT '',\n  body_md     TEXT    NOT NULL DEFAULT '',\n  ref         TEXT,\n  status      TEXT    NOT NULL DEFAULT 'draft',   -- draft | harvested | dismissed\n  FOREIGN KEY (book_id) REFERENCES books(id)\n);\n""#).expect("KNOWLEDGE_SCHEMA: embedded JSON is valid by construction")
});

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::Value;

    #[test]
    fn timeline_schema_parses_with_the_pressed_shape() {
        let v: &Value = &TIMELINE_SCHEMA;
        assert_eq!(v.as_str().expect("string").chars().count(), 3810, "pressed char length");
    }

    #[test]
    fn judgments_schema_parses_with_the_pressed_shape() {
        let v: &Value = &JUDGMENTS_SCHEMA;
        assert_eq!(v.as_str().expect("string").chars().count(), 3605, "pressed char length");
    }

    #[test]
    fn state_schema_parses_with_the_pressed_shape() {
        let v: &Value = &STATE_SCHEMA;
        // 55383 → 56907: code_onboard_jobs moved in from the code schema (with its rationale).
        assert_eq!(v.as_str().expect("string").chars().count(), 56907, "pressed char length");
        // The move is the point, so assert it rather than trusting a char count to imply it.
        assert!(v.as_str().unwrap().contains("CREATE TABLE IF NOT EXISTS code_onboard_jobs"),
                "the job table must be in STATE (main) — in `code` it is invisible during a staged rebuild");
    }

    #[test]
    fn memory_schema_parses_with_the_pressed_shape() {
        let v: &Value = &MEMORY_SCHEMA;
        assert_eq!(v.as_str().expect("string").chars().count(), 10564, "pressed char length");
    }

    #[test]
    fn brain_schema_parses_with_the_pressed_shape() {
        let v: &Value = &BRAIN_SCHEMA;
        // 36096 -> 36432: `outcome_class` joined the ai_calls DDL (2691a6b). Stale on every host, not a CRLF matter.
        assert_eq!(v.as_str().expect("string").chars().count(), 36432, "pressed char length");
    }

    #[test]
    fn laws_schema_parses_with_the_pressed_shape() {
        let v: &Value = &LAWS_SCHEMA;
        assert_eq!(v.as_str().expect("string").chars().count(), 6067, "pressed char length");
    }

    #[test]
    fn knowledge_schema_parses_with_the_pressed_shape() {
        let v: &Value = &KNOWLEDGE_SCHEMA;
        // 16820 → 18462: narration_press_progress. Press telemetry had to leave the addon's
        // process-local map to be readable from outside the thread doing the pressing.
        assert_eq!(v.as_str().expect("string").chars().count(), 18462, "pressed char length");
        // A char count cannot say WHICH table arrived, so assert the thing that matters.
        assert!(v.as_str().unwrap().contains("CREATE TABLE IF NOT EXISTS knowledge.narration_press_progress"),
                "a detached press is only observable if its progress lives in the db, not in addon statics");
    }

}
